(window.TNQ=window.TNQ||[]).push({"terms":{"연속체":{"d":"분자 사이 빈틈을 무시하고 물질이 빈틈없이 채워진 것으로 보는 해석상 가정입니다.","r":["유체"]},"유체":{"d":"힘을 받으면 흘러 모양이 변하는 물질로 액체와 기체를 가리킵니다.","r":["연속체"]},"뉴턴 유체":{"d":"전단응력이 속도경사에 비례하는 유체로 점성계수가 일정합니다.","r":["이상유체","점성계수"]},"이상유체":{"d":"점성이 없고 압축되지 않는다고 가정한 이론상의 유체입니다.","r":["뉴턴 유체"]},"단위중량":{"d":"단위 부피당 중량으로 밀도에 중력가속도를 곱한 값입니다.","r":["비중"]},"비중":{"d":"물질의 밀도를 기준 물질인 물의 밀도로 나눈 단위 없는 값입니다.","r":["단위중량"]},"비체적":{"d":"단위 질량이 차지하는 부피로 밀도의 역수입니다.","r":[]},"점성계수":{"d":"전단응력과 속도경사 사이의 비례상수로 변형에 대한 저항의 크기입니다.","r":["동점성계수","뉴턴 유체"]},"동점성계수":{"d":"점성계수를 밀도로 나눈 값으로 유체의 운동 저항 정도를 나타냅니다.","r":["점성계수"]},"표면장력":{"d":"액체 표면이 스스로 줄어들려는 힘으로 단위 길이당 힘으로 나타냅니다.","r":["접촉각"]},"접촉각":{"d":"액체가 고체 표면과 만나는 곳에서 액면과 고체면이 이루는 각입니다.","r":["표면장력"]},"엔트로피":{"d":"계의 무질서한 정도를 나타내는 상태함수로 자연 변화에서 늘어납니다.","r":[]},"전압력":{"d":"유체가 평면 전체에 가하는 압력의 합력으로 크기를 힘으로 나타냅니다.","r":["부력"]},"부력":{"d":"유체에 잠긴 물체가 받는 위쪽 힘으로 밀려난 유체의 무게와 같습니다.","r":["전압력"]},"정상류":{"d":"한 점의 속도와 압력 같은 유동 특성이 시간에 따라 변하지 않는 흐름입니다.","r":["비정상류"]},"비정상류":{"d":"같은 지점에서도 유동 특성이 시간에 따라 변하는 흐름입니다.","r":["정상류"]},"프루드수":{"d":"유속과 표면파 전파속도의 비로 상류, 사류, 한계류를 가르는 무차원수입니다.","r":["상류","사류"]},"상류":{"d":"프루드수가 1보다 작아 유속이 파의 전파속도보다 느린 개수로 흐름입니다.","r":["사류","프루드수"]},"사류":{"d":"프루드수가 1보다 커 유속이 파의 전파속도보다 빠른 개수로 흐름입니다.","r":["상류","프루드수"]},"레이놀즈수":{"d":"관성력과 점성력의 비로 층류와 난류를 가르는 무차원수입니다.","r":["층류","난류"]},"층류":{"d":"유체가 층을 이루어 섞이지 않고 질서 있게 흐르는 상태입니다.","r":["난류","레이놀즈수"]},"난류":{"d":"유체가 불규칙하게 섞이며 흐르는 상태입니다.","r":["층류","레이놀즈수"]},"연속방정식":{"d":"질량보존 법칙을 유체 흐름에 적용한 식으로 단면마다 질량유량이 같음을 나타냅니다.","r":["베르누이 방정식"]},"베르누이 방정식":{"d":"같은 유선에서 압력수두, 속도수두, 위치수두의 합이 일정하다는 에너지 보존식입니다.","r":["연속방정식"]},"동수경사선":{"d":"압력수두와 위치수두의 합을 이은 선으로 에너지선보다 속도수두만큼 낮습니다.","r":["에너지선"]},"에너지선":{"d":"압력수두, 위치수두에 속도수두까지 더한 전수두를 이은 선입니다.","r":["동수경사선"]},"미소손실":{"d":"관로의 급확대, 급축소, 밸브, 엘보 같은 부속에서 생기는 부차적 손실입니다.","r":[]},"상대조도":{"d":"관 내면 거칠기를 관 지름으로 나눈 값으로 난류의 마찰손실계수를 좌우합니다.","r":[]},"공동현상":{"d":"펌프 안 압력이 포화증기압 가까이 낮아져 액체가 증발해 기포가 생기는 현상입니다.","r":[]},"비속도":{"d":"펌프의 형식과 성능을 비교하는 값으로 회전수, 유량, 양정으로 계산합니다.","r":[]},"원심펌프":{"d":"임펠러의 회전으로 생긴 원심력으로 물에 압력을 주는 터보형 펌프입니다.","r":[]},"축동력":{"d":"전동기가 펌프 축에 실제로 전달하는 동력으로 수동력을 효율로 나눈 값입니다.","r":["수동력"]},"수동력":{"d":"펌프가 물에 실제로 주는 동력으로 단위중량, 유량, 양정의 곱입니다.","r":["축동력"]},"융해열":{"d":"고체가 액체로 바뀔 때 온도 변화 없이 흡수하는 열량입니다.","r":["증발잠열"]},"증발잠열":{"d":"액체가 기체로 바뀔 때 온도 변화 없이 흡수하는 열량입니다.","r":["융해열"]},"강화액":{"d":"알칼리 금속염류 수용액을 주성분으로 하는 수계 소화약제입니다.","r":[]},"수성막포":{"d":"탄화불소계 계면활성제로 기름 표면에 수성막을 만들어 끄는 포 소화약제입니다.","r":["알코올형포"]},"알코올형포":{"d":"수용성 용제 화재에 쓰는 포 소화약제입니다.","r":["수성막포"]},"환원시간":{"d":"포의 25 %가 거품에서 포수용액으로 되돌아오는 데 걸리는 시간입니다.","r":["발포배율"]},"발포배율":{"d":"만들어진 포의 부피를 포수용액의 부피로 나눈 값입니다.","r":["환원시간"]},"렌츠의 법칙":{"d":"유도기전력이 자속의 변화를 방해하는 방향으로 생긴다는 법칙입니다.","r":[]},"임피던스":{"d":"교류 회로에서 저항과 리액턴스를 합한 전류의 방해 정도입니다.","r":[]},"역률":{"d":"피상전력 중 유효전력이 차지하는 비율로 위상각의 코사인 값입니다.","r":["유효전력","피상전력"]},"피상전력":{"d":"전압과 전류 실효값의 곱으로 나타내는 겉보기 전력입니다.","r":["유효전력","역률"]},"유효전력":{"d":"부하에서 실제로 일로 소비되는 전력입니다.","r":["피상전력","역률"]},"켤레복소수":{"d":"허수부의 부호만 반대인 복소수로 최대 전력 전달 조건에 쓰입니다.","r":[]},"자기유지":{"d":"출력을 입력으로 되먹여 시동 입력이 꺼져도 출력이 유지되는 회로 방식입니다.","r":["인터록"]},"인터록":{"d":"한쪽이 동작하면 다른 쪽이 동작하지 못하게 서로 막는 회로 방식입니다.","r":["자기유지"]},"충전비":{"d":"용기 내용적을 약제 중량으로 나눈 값입니다.","r":[]},"설계농도":{"d":"소화농도에 안전율을 곱해 정한 방호구역의 약제 농도입니다.","r":[]},"소화밀도":{"d":"규정 화재를 끄는 데 필요한 단위 체적당 약제 질량입니다.","r":["설계농도"]},"교차회로방식":{"d":"두 개 이상 감지기 회로가 함께 감지해야 설비가 작동하는 방식입니다.","r":[]},"방호구역":{"d":"소화설비가 약제를 방출해 보호하는 구획된 공간입니다.","r":[]},"선택밸브":{"d":"여러 방호구역 가운데 불이 난 구역으로만 약제를 보내도록 여는 밸브입니다.","r":["방호구역"]},"금수성 물질":{"d":"물과 반응해 수소 같은 가연성 가스를 내는 물질입니다.","r":[]},"팽창질석":{"d":"금속화재 표면을 덮어 공기를 막는 데 쓰는 질석 계열 약제입니다.","r":[]}},"notes":{"(20±0.5) ℃에서 설계값 ±0.02 이내. 사용온도는 5 ℃ 단위로 구분.":"포 약제 비중은 20 ℃ 부근에서 설계값과 0.02 이내로 맞아야 하고 사용온도는 5 ℃ 간격으로 구분합니다.","(22.4/18)×(473/273) = 2.156 L = 2,156 cm³ → 약 2,156배.":"물이 473 K 수증기가 되면 부피가 약 2,156배로 늘어납니다.","(A·B)의 부정 = A̅ + B̅, (A + B)의 부정 = A̅·B̅.":"드모르간 정리는 곱의 부정이 부정의 합이 되고 합의 부정이 부정의 곱이 된다는 정리입니다.","(가연성 액체·가스 등) 방호구역 체적 1 ㎥당 표의 양. 표의 양이 최저한도 미만이면 최저한도의 양으로 한다.":"표면화재 전역방출은 방호구역 체적 1 ㎥당 표의 양이며 표의 양이 최저한도보다 적으면 최저한도를 씁니다.","(보충, 원문 제4조 표는 이미지라 텍스트 미확인) HCFC-124 1.0 %, HFC-125 11.5 %, HFC-227ea 10.5 %, HFC-23 30 %, HFC-236fa 12.5 %, FIC-13I1 0.3 %, FK-5-1-12 10 %, FC-3-1-10 40 %, HCFC BLEND A 10 %.":"최대허용 설계농도는 약제마다 달라 HCFC-124 1.0 %, HFC-125 11.5 %, HFC-23 30 %처럼 정해집니다.","(보충, 표는 원문 이미지로 텍스트 미확인) 45 ㎥ 미만 1.00 kg/㎥(최저 45 kg), 45~150 ㎥ 0.90 kg/㎥(최저 45 kg), 150~1,450 ㎥ 0.80 kg/㎥(최저 135 kg), 1,450 ㎥ 이상 0.75 kg/㎥(최저 1,125 kg).":"체적이 커질수록 1 ㎥당 약제량은 1.00에서 0.75 kg으로 줄고 최저 약제량 한도가 따로 있습니다.","(보충, 표는 원문 이미지로 텍스트 미확인) 메탄·부탄 34 %, 프로판·이소부탄 36 %, 에탄 40 %, 에틸렌 49 %, 산화에틸렌 53 %, 일산화탄소 64 %, 아세틸렌 66 %, 수소 75 %.":"가연성가스별 설계농도는 가스마다 달라 메탄·부탄은 34 %, 에탄 40 %, 수소 75 % 등으로 정해집니다.","(보충, 표는 원문 이미지로 텍스트 미확인) 종이·목재·석탄·섬유류·합성수지류 1.3 kg/㎥(설계농도 50 %), 전기설비 1.3 kg/㎥(55 ㎥ 미만은 1.6 kg/㎥, 50 %), 서고·전자제품창고·목재가공품창고·박물관 2.0 kg/㎥(65 %), 고무류·면화류 창고·모피창고·석탄창고·집진설비 2.7 kg/㎥(75 %).":"심부화재 약제량은 대상에 따라 1.3 kg/㎥(설계농도 50 %)부터 2.7 kg/㎥(75 %)까지 달라집니다.","(보충, 표 텍스트 미확인) 체적 1 ㎥당 제1종 0.60 kg, 제2종·제3종 0.36 kg, 제4종 0.24 kg. 개구부 1 ㎡당 제1종 4.5 kg, 제2종·제3종 2.7 kg, 제4종 1.8 kg.":"체적 1 ㎥당 제1종 0.60 kg, 제2종·제3종 0.36 kg, 제4종 0.24 kg이고 개구부는 1 ㎡당 제1종 4.5 kg입니다.","(종이·목재·석탄·섬유류·합성수지류) 방호구역 체적 1 ㎥에 대하여 표의 양 이상.":"심부화재는 종이, 목재, 석탄, 섬유류, 합성수지류에서 번지는 불이며 체적 1 ㎥당 표의 양 이상을 둡니다.","0.1 vol% 이하, 변질시험 후 0.2 vol% 이하.":"강화액 침전량은 0.1 vol% 이하이며 변질시험 후에도 0.2 vol% 이하여야 합니다.","0.8 g/mL 이상(설계값 ±0.1). 분말을 수면에 살포하면 1시간 이내에 침강하지 않아야 한다.":"겉보기비중은 0.8 g/mL 이상이며 수면에 뿌린 분말은 1시간 안에 가라앉지 않아야 합니다.","0.90 이상 1.20 이하는 2023 기출에서 옳은 선지로 출제(현행 비중표는 이미지 표라 원문 텍스트 미확인).":"알코올형포 비중의 범위를 0.90 이상 1.20 이하로 제시한 선지입니다.","100℃ 수증기: 80 + 539.6 = 약 619.6 cal.":"물을 100℃ 수증기로 만들 때 가열분 80에 증발잠열 539.6을 더해 약 619.6 cal입니다.","100℃ 수증기: 현열 85 kcal(355.3 kJ) + 증발잠열 539 kcal(2,253 kJ) = 약 624 kcal. 이 과정에는 용융잠열이 없다.":"물을 수증기로 만드는 열량은 현열 85 kcal와 증발잠열 539 kcal의 합이며 용융잠열은 없습니다.","10 V, 상단 3 Ω·3 Ω, 하단 1 Ω·1 Ω, 가운데 3 Ω: 3:1 = 3:1로 평형 → (3+1)와 (3+1)의 병렬 = 2 Ω → I = 10 ÷ 2 = 5 A.":"비 3 대 1이 위아래에서 같아 평형이므로 가운데를 빼고 병렬 합성저항 2 Ω으로 10 V를 나누면 5 A입니다.","1 HP = 0.746 kW, 1 PS = 0.735 kW.":"1 HP는 0.746 kW, 1 PS는 0.735 kW로 마력 단위마다 킬로와트 환산값이 다릅니다.","1 g 물(1 cm³)이 수증기가 되면 이상기체식으로 V = (1/18)·22.4·(T/273) L.":"물 1 g이 수증기가 되는 부피는 몰수 18분의 1에 22.4 L와 온도비를 곱해 구합니다.","1 Ω 저항 3개의 T형 회로: Y₁₁ = Y₂₂ = 2/3 S, Y₁₂ = Y₂₁ = −1/3 S. 상반 회로라 Y₁₂ = Y₂₁.":"1 Ω 저항 3개 T형 회로의 Y₁₁과 Y₂₂는 2/3 S이고 Y₁₂와 Y₂₁은 서로 같은 상반 회로 값입니다.","2.1 ㎫(저압식 1.05 ㎫) 이상.":"분사헤드 방출압력은 2.1 ㎫ 이상이고 저압식은 1.05 ㎫ 이상입니다.","200 L/min = 3.333×10⁻³ m³/s. 40 mm 호스 유속 2.65 m/s, 20 mm로 줄이면 10.61 m/s → 증가분 약 7.95 m/s.":"200 L/min은 3.333×10⁻³ m³/s이며 호스를 40 mm에서 20 mm로 줄이면 유속이 10.61 m/s로 늘어납니다.","2KHCO₃ + (NH₂)₂CO → K₂CO₃ + 2NH₃ + 2CO₂.":"탄산수소칼륨과 요소가 반응해 탄산칼륨, 암모니아, 이산화탄소를 냅니다.","2KHCO₃ → K₂CO₃ + CO₂ + H₂O (약 190 ℃에서 분해, 흡열).":"제2종 분말은 약 190 ℃에서 흡열 분해되어 탄산칼륨, 이산화탄소, 물을 냅니다.","2NaHCO₃ → Na₂CO₃ + CO₂ + H₂O (약 270 ℃ 이상에서 분해, 흡열).":"약 270 ℃ 이상에서 열을 흡수하며 분해되어 탄산나트륨, 이산화탄소, 물이 됩니다.","30 cm 관 1.5 m/s → 20 cm 관: V₂ = 1.5 × (30/20)² = 3.375 m/s.":"관이 30 cm에서 20 cm로 가늘어지면 유속은 지름비 제곱만큼 늘어 3.375 m/s가 됩니다.","33 mN/m 이하(K급 화재용 포함 약제는 적용하지 않음). 비중은 설계값 ±0.02, pH는 6~9(설계값 ±0.4).":"강화액 표면장력은 33 mN/m 이하이고 비중은 설계값 ±0.02, pH는 6에서 9 범위입니다.","3병 이상 설치한 경우 2개 이상의 용기에 전자개방밸브를 부착한다. 압력조정기는 2.5 ㎫ 이하에서 조정 가능한 것.":"가압용 가스용기가 3병 이상이면 2개 이상에 전자개방밸브를 달고 압력조정기는 2.5 ㎫ 이하에서 조정되는 것을 씁니다.","500회, 0.8 Wb → 0.6 Wb, 0.5초: e = 500 × 0.2 ÷ 0.5 = 200 V.":"500회 감은 코일에서 자속이 0.8 Wb에서 0.6 Wb로 0.5초에 변하면 유도기전력은 200 V입니다.","600 kg, 68 L: 정답 15병은 충전비 1.6~1.7 정도를 적용했을 때 나온다(문항에 충전비 조건 누락, 추정). 충전비 1.7이면 40 kg/병 → 15병.":"600 kg을 68 L 용기에 담을 때 정답 15병은 충전비 1.6~1.7을 적용해야 나오는데 문항에 충전비가 빠졌습니다.","60±2 ℃에서 7일 보존, 실온 3일 보존 후 유동성이 있고 고화되지 않아야 한다. C급 화재용은 5,000 V 교류 절연내력시험.":"온도상승시험은 60±2 ℃에서 7일, 실온에서 3일 보존한 뒤 분말이 굳지 않고 유동성이 있어야 합니다.","65±2 ℃에서 216시간 보존 후 실온 환원, 다시 -18±2 ℃에서 24시간 보존 후 실온 환원.":"변질시험은 65±2 ℃에서 216시간 보관하고 실온으로 되돌린 뒤 -18±2 ℃에서 24시간 보관해 상태를 봅니다.","= (21 − 한계산소농도) ÷ 21 × 100 (무유출 방식). 예) 산소를 10 vol%로 낮추려면 (21 − 10) ÷ 21 × 100 = 52.38 vol%.":"이산화탄소 농도는 산소 21에서 한계산소농도를 뺀 값을 21로 나눠 100을 곱하며 이 예는 52.38 vol%입니다.","= 101.325 kPa = 760 mmHg = 10.33 mH₂O = 1.0332 kgf/cm².":"1기압은 여러 단위로 나타내며 101.325 kPa, 760 mmHg, 10.33 mH₂O와 같습니다.","= 10 mH₂O = 98.07 kPa. 예) 2.2 kgf/cm² = 22 mH₂O(압력수두).":"이 압력 단위는 물기둥 10 m 높이와 같아 2.2 kgf/cm²는 22 mH₂O로 환산됩니다.","= 발생한 포의 부피 ÷ 포수용액의 부피.":"발포배율은 만들어진 포의 부피를 포수용액 부피로 나눈 값입니다.","= 부력 = 밀어낸 물의 무게(아르키메데스 원리).":"수중에서 줄어든 무게는 물이 밀어 올리는 부력이고, 이는 밀려난 물의 무게와 같다는 아르키메데스 원리입니다.","= 용기 내용적 ÷ 충전비. 필요 병수 = 약제량 ÷ 병당 충전량(올림).":"병당 충전량은 용기 내용적을 충전비로 나눈 값이고 필요한 병수는 약제량을 그 값으로 나눠 올립니다.","= 원액 ÷ 농도. 예) 원액 12 L, 3 % → 수용액 400 L = 0.4 m³. 포 4 m³ → 4 ÷ 0.4 = 10배.":"포수용액 부피는 원액을 농도로 나눠 구하며 이 예는 400 L로, 포 4 m³는 10배가 됩니다.","= 위치수두 + 압력수두 + 속도수두. 마찰손실수두는 전수두의 구성이 아니다.":"이상유체의 전수두는 위치, 압력, 속도수두의 합이고 마찰손실수두는 이 합에 들지 않습니다.","= 최소소화농도 × 안전율(약 1.2). 예) 부탄 최소소화농도 28 %, 최소설계농도 34 %.":"설계농도는 최소소화농도에 안전율 약 1.2를 곱한 값이며 부탄은 28 %에서 34 %가 됩니다.","A, B의 모든 조합(00, 01, 10, 11)에서 X의 값을 읽어 진리표를 만든 뒤 논리식에 대응시킨다. A, B가 서로 다를 때만 X가 1이면 XOR.":"입력 조합 00, 01, 10, 11마다 X 값을 읽어 진리표를 만들고 A와 B가 다를 때만 X가 1이면 XOR입니다.","ABC급 분말을 사용하면 부촉매 효과로 소화할 수 있다.":"전기화재에 ABC급 분말을 쓰면 연쇄반응을 억제하는 부촉매 효과로 끌 수 있습니다.","AND: X = A·B (둘 다 1일 때만 1). OR: X = A + B (하나라도 1이면 1). NOT: X = A̅.":"AND는 입력이 모두 1일 때만 1, OR는 하나라도 1이면 1, NOT은 입력을 뒤집습니다.","A급(일반), B급(유류), C급(전기), D급(금속), K급(주방·식용유).":"화재는 A급 일반, B급 유류, C급 전기, D급 금속, K급 주방·식용유로 나눕니다.","C + O₂ → CO₂(발열, 약 94 kcal/mol).":"탄소가 완전연소하여 이산화탄소가 될 때 약 94 kcal/mol의 열이 납니다.","C = Q/V. 평행판 콘덴서 C = εA/d. 저장 에너지 W = ½CV².":"정전용량은 전하를 전압으로 나눈 값이고 평행판은 면적에 비례, 간격에 반비례하며 저장 에너지는 용량과 전압 제곱에 비례합니다.","CF₃Br(할론 1301)의 주된 소화방법은 억제소화.":"CF₃Br로 표기되는 할론 1301은 억제소화로 불을 끕니다.","CF₃Br을 억제소화의 옳은 연결로, HFC-125와 NH₄H₂PO₄의 연결을 틀린 연결로 출제했다.":"CF₃Br은 억제소화와 짝이 맞고 HFC-125와 NH₄H₂PO₄ 연결은 틀린 연결이라는 내용입니다.","CHClFCF₃. HCFC 계열이다(HFC 계열이 아니다).":"염소를 함유한 HCFC 계열이며 HFC 계열이 아닙니다.","CH₄ + 2O₂ → CO₂ + 2H₂O.":"메탄이 산소 2분자와 반응해 이산화탄소와 물 2분자를 만드는 연소 반응식입니다.","F = q₁q₂ ÷ (4πε₀r²) = 9×10⁹ q₁q₂/r². 자기 쿨롱 법칙도 같은 형태.":"쿨롱의 법칙은 두 전하 사이 힘이 전하량의 곱에 비례하고 거리 제곱에 반비례하며 자기 쿨롱 법칙도 같은 꼴입니다.","F = μ₀I₁I₂ ÷ (2πd) (N/m). 같은 방향 전류는 인력, 반대 방향은 척력. 예) 2 m, 1 A, 1 A → μ₀ ÷ 4π, 인력.":"평행한 두 도체에 같은 방향 전류가 흐르면 서로 끌어당기고 반대 방향이면 밀어내며 힘은 간격에 반비례합니다.","FC-3-1-10: C₄F₁₀ (퍼플루오로부탄). FK-5-1-12: 도데카플루오로-2-메틸펜탄-3-온(불소·탄소·산소로 구성). FIC-13I1: 트리플루오로요다이드(CF₃I).":"FC-3-1-10은 퍼플루오로부탄, FK-5-1-12는 불소·탄소·산소로 된 케톤, FIC-13I1은 CF₃I입니다.","F_B = γ·V(잠긴 체적). 부력은 밀어낸 유체의 무게와 같다.":"부력은 잠긴 부피만큼 밀려난 유체의 무게와 같아 단위중량에 잠긴 체적을 곱해 구합니다.","G = G₁ ÷ (1 + G₁G₂). 정궤환은 분모 1 − G₁G₂.":"부궤환 접속의 합성 전달함수는 G₁을 1 더하기 G₁G₂로 나눈 값이고 정궤환은 분모가 1 빼기 G₁G₂입니다.","HCFC-124, HFC-125, HFC-227ea, HFC-23, 할론 1211, HFC-236fa, FIC-13I1, FK-5-1-12는 99.0 mol% 이상. 할론 1301은 99.6 mol% 이상.":"순도는 대부분의 할로겐화합물이 99.0 mol% 이상이고 할론 1301만 99.6 mol% 이상입니다.","HCFC-124 1.0 %, HFC-236fa 12.5 %, HFC-23 30 %는 옳은 선지, IG-100 30 %는 틀린 선지.":"IG-100에 30 %를 붙인 것만 틀리고 HCFC-124, HFC-236fa, HFC-23의 농도는 표와 맞습니다.","HCFC BLEND A(HCFC-22 82 wt%, HCFC-124 9.5 wt%, HCFC-123 4.75 wt%, 이소프로페닐-1-메틸시이클로헥센 3.75 wt%). HFC BLEND B(HFC-134a 86 wt%, HFC-125 9.0 wt%, 이산화탄소 5 wt%).":"혼합 약제인 HCFC BLEND A와 HFC BLEND B는 성분별 중량 퍼센트로 조성이 정해집니다.","HFC-23: CHF₃. HFC-125: CHF₂CF₃. HFC-227ea: CF₃CHFCF₃. HFC-236fa: CF₃CH₂CF₃.":"HFC-23, HFC-125, HFC-227ea, HFC-236fa의 화학식을 나열한 것으로 모두 수소·불소·탄소 화합물입니다.","IG-01: 아르곤 99.9 vol% 이상. IG-100: 질소 99.9 vol% 이상. IG-55: 질소 50±5 vol%, 아르곤 50±5 vol%.":"IG-01은 아르곤, IG-100은 질소가 99.9 vol% 이상이고 IG-55는 질소와 아르곤이 각각 50±5 vol%입니다.","L = μN²A/ℓ. 코일 안에 삽입된 물질의 투자율에 비례한다.":"자기인덕턴스는 코일 감은 수의 제곱과 단면적에 비례하고 코일 안 물질의 투자율에도 비례합니다.","M 150 mH, 5 A → 20 A, 0.5초: e = 0.15 × 15 ÷ 0.5 = 4.5 V.":"상호인덕턴스 150 mH에서 전류가 0.5초 동안 5 A에서 20 A로 변하면 유도기전력은 4.5 V입니다.","NAND: X = (A·B)의 부정. NOR: X = (A + B)의 부정. XOR(배타적 논리합): X = A̅·B + A·B̅. XNOR: X = A·B + A̅·B̅.":"NAND와 NOR는 AND와 OR의 부정이고 XOR는 두 입력이 다를 때, XNOR는 같을 때 참입니다.","NH₄H₂PO₄ → NH₃ + H₃PO₄(오르토인산, 약 190 ℃) → H₄P₂O₇(피로인산, 약 215 ℃) → HPO₃(메타인산, 약 300 ℃).":"열을 받으면 암모니아와 오르토인산을 거쳐 피로인산, 메타인산으로 차례로 분해됩니다.","NPSHav = 대기압수두 − 포화증기압수두 − 흡입손실수두 − 흡입 실양정(수면이 펌프보다 낮을 때). 수면이 펌프보다 높으면 실양정을 더한다.":"NPSHav는 대기압수두에서 포화증기압수두, 흡입손실, 흡입 실양정을 빼며 수면이 높으면 실양정을 더합니다.","N_s = N·√Q ÷ H^(3/4). N은 회전수(rpm), Q는 유량(m³/min), H는 양정(m). 각속도 ω가 아니라 회전수 N을 쓴다.":"비속도는 회전수와 유량의 제곱근을 양정의 4분의 3제곱으로 나눈 값이며 각속도가 아닌 회전수를 씁니다.","Na, K 등은 물과 만나면 수소가스를 발생시키는 금수성 물질이다. 리튬·나트륨에 수계 소화약제를 쓰면 폭발성이 강한 수소를 발생시킨다.":"나트륨과 칼륨은 물과 만나 수소가스를 내는 금수성 물질이라 수계 약제를 쓰면 폭발 위험이 커집니다.","ODP가 0인 할로겐화합물 소화약제: HFC-23, FC-3-1-10, FK-5-1-12. HCFC-124는 염소를 포함하여 ODP가 0이 아니다.":"ODP가 0인 약제는 HFC-23, FC-3-1-10, FK-5-1-12이며 염소가 든 HCFC-124는 0이 아닙니다.","P/γ + V²/2g + Z = 일정(압력수두 + 속도수두 + 위치수두).":"베르누이 방정식은 압력수두, 속도수두, 위치수두의 합이 같은 유선에서 일정하다는 식입니다.","P = V·I·cos(θ_v − θ_i), V, I는 실효값. 예) v = √2·220·sin(377t + π/3), i = √2·4·sin(377t + π/6): 위상차 π/6(30°) → P = 220 × 4 × cos30° = 440√3 W.":"소비전력은 전압과 전류 실효값에 두 위상차의 cos를 곱하며 이 예는 위상차 30°라 440√3 W입니다.","P = W₁ + W₂. 예) 800 W + 600 W = 1,400 W.":"두 전력계 지시값의 합이 유효전력이며 800 W와 600 W면 1,400 W입니다.","P = γQH ÷ η. 전동기 동력 = 축동력 × 전달계수 K.":"축동력은 수동력을 펌프 효율로 나눈 값이고 전동기 동력은 여기에 전달계수를 곱합니다.","P = √3·V_l·I_l·cosθ = 3·V_p·I_p·cosθ.":"3상 전력은 선간전압과 선전류의 곱에 3의 제곱근과 역률을 곱한 값이고 상 기준으로는 3배입니다.","PV = nRT = (m/M)RT, P = ρRT. R은 특정 이상기체마다 정해진 값(R = 일반기체상수 ÷ 분자량).":"이상기체 상태방정식에서 R은 기체마다 다른 값이며, 일반기체상수를 분자량으로 나누어 얻습니다.","P_w = γ·Q·H = 9.8·Q·H (kW, Q m³/s, H m).":"수동력은 단위중량, 유량, 전양정의 곱이며 물이면 9.8에 유량과 양정을 곱한 킬로와트입니다.","Pa·s = N·s/m² = kg/(m·s). CGS는 poise(P) = g/(cm·s). 1 P = 0.1 Pa·s.":"점성계수 단위는 Pa·s이고, CGS 단위 poise는 0.1 Pa·s에 해당합니다.","Q 2배, H 4배, P 8배.":"회전수를 2배로 올리면 유량 2배, 양정 4배, 축동력 8배가 됩니다.","Q = AV = (πD²/4)V. 지름이 같은 비율로 변하면 유속은 지름 제곱에 반비례한다.":"유량은 단면적에 유속을 곱한 값이라 유량이 같으면 유속은 지름 제곱에 반비례합니다.","Q₂ = Q₁(N₂/N₁), H₂ = H₁(N₂/N₁)², P₂ = P₁(N₂/N₁)³.":"지름이 같으면 회전수 비에 유량은 그대로, 양정은 제곱, 동력은 세제곱을 곱합니다.","Q를 m³/s로 → 유속 V = Q ÷ (πD²/4) → Re = VD/ν. 예) 250 mm 관, 40 L/s → V = 0.815 m/s. 정답 1,698은 ν ≈ 1.2×10⁻⁴ m²/s일 때 나온다(문항에 동점성계수 조건 누락, 추정).":"유량을 단면적으로 나눠 유속을 구한 뒤 레이놀즈수에 대입하며, 정답은 동점성계수를 추정해야 나옵니다.","R-C 직렬회로에서 전류는 전압보다 tan⁻¹(1/(ωCR)) 만큼 앞선다.":"R-C 직렬회로는 전류가 전압보다 앞서며 앞선 각은 역탄젠트 식으로 구합니다.","R-L 직렬 가지에 C 병렬: 공진 시 임피던스 Z = L/(RC) (최대).":"R-L 직렬 가지에 C를 병렬로 이은 회로는 공진 때 임피던스가 L/(RC)로 최대가 됩니다.","R-L 직렬회로에서 전류는 전압보다 θ = tan⁻¹(ωL/R) 만큼 뒤진다.":"코일이 있는 R-L 직렬회로는 전류가 전압보다 위상이 뒤지며 그 각을 역탄젠트로 구합니다.","Re = ρVD/μ = VD/ν. 관성력과 점성력의 비.":"레이놀즈수는 관성력과 점성력의 비이며 밀도, 유속, 지름의 곱을 점성계수로 나눠 구합니다.","R만 전력을 소비한다: P = I²R.":"교류 회로에서 전력을 소비하는 소자는 저항뿐이며 전력은 전류 제곱에 저항을 곱한 값입니다.","S = h_f/L = f·V²/(2gD). 층류면 f = 64/Re를 먼저 구한다. 예) D 10 cm, 0.5 L/s → V = 0.0637 m/s, 정답 2.08×10⁻⁴는 f ≈ 0.10(Re ≈ 640)일 때 나온다(문항에 동점성계수 조건 누락, 추정).":"에너지선 경사는 손실수두를 길이로 나눈 값이며, 층류이면 f를 먼저 구하는데 문항에 동점성계수 조건이 빠졌습니다.","V = IR. 저항 R = ρℓ/A (저항률 ρ, 길이 ℓ, 단면적 A). 저항은 길이에 비례하고 단면적에 반비례한다.":"옴의 법칙은 전압이 전류와 저항의 곱이고 저항은 길이에 비례, 단면적에 반비례하는 법칙입니다.","V = √(2g·h·(S액/S물 − 1)). 마노미터 액체 수은 비중 13.6. 예) 수은 액면차 0.5 m → V = √(2×9.8×0.5×12.6) = 약 11.1 m/s.":"피토관 유속은 액체와 물의 비중비에서 1을 뺀 값과 액면차로 구하며 이 예는 약 11.1 m/s입니다.","V₂ ≈ 0이면 h = V₁²/2g. 예) 지름 10 cm, 0.2 m³/s → V = 25.46 m/s → h = 648.4 ÷ 19.6 = 33.08 m.":"수조가 매우 커서 나중 유속이 거의 0이면 손실수두는 처음 유속의 속도수두와 같습니다.","W = V/S × C/(100 − C). W 약제량(kg), V 방호구역 체적(㎥), S 소화약제별 비체적(㎥/kg), C 설계농도(%). S = K₁ + K₂·t.":"할로겐화합물 약제량은 체적을 비체적으로 나눈 값에 설계농도를 100에서 뺀 값으로 나눈 비를 곱합니다.","X = 2.303 × (V_s/S) × log₁₀[100/(100 − C)]. V_s 20 ℃ 비체적.":"불활성기체 약제량은 2.303에 비체적비를 곱하고 100/(100 − C)의 상용로그를 곱해 구하며 20 ℃ 비체적을 씁니다.","X_L = X_C, 공진주파수 f = 1/(2π√(LC)), 이때 Z = R(최소), 전류 최대, 역률 1.":"직렬 공진은 X_L과 X_C가 같아져 임피던스가 저항뿐이 되고 전류가 최대, 역률이 1이 됩니다.","X_L = ωL, X_C = 1/(ωC). 임피던스 Z = R + j(X_L − X_C), |Z| = √(R² + (X_L − X_C)²).":"리액턴스는 코일이 ωL, 콘덴서가 1/(ωC)이며 임피던스는 저항에 리액턴스 차를 허수로 더해 구합니다.","Y₁₁ = I₁/V₁ (V₂ = 0), Y₁₂ = I₁/V₂ (V₁ = 0), Y₂₁ = I₂/V₁ (V₂ = 0), Y₂₂ = I₂/V₂ (V₁ = 0).":"두 단자쌍 회로의 Y 파라미터는 한쪽 단자를 단락한 채 전류를 전압으로 나눠 정의합니다.","[FL] = [ML²T⁻²].":"에너지는 일과 같은 차원이라 힘에 길이를 곱한 꼴이며 질량계로는 ML²T⁻²입니다.","[FL⁻³] = [ML⁻²T⁻²].":"단위중량은 부피당 힘의 차원이고 질량계로 바꾸면 질량을 길이 제곱과 시간 제곱으로 나눈 꼴입니다.","[FL⁻¹] = [MT⁻²].":"표면장력은 길이당 힘의 차원이며, 질량계로는 질량을 시간 제곱으로 나눈 꼴이 됩니다.","[FL⁻⁴T²] = [ML⁻³]. 단위중량의 차원이 아니다.":"밀도의 차원은 단위중량과 다르며 힘계 표기로는 FL⁻⁴T²입니다.","[L²T⁻¹]. MLT와 FLT에서 같다.":"동점성계수는 길이 제곱을 시간으로 나눈 차원이라 MLT계와 FLT계에서 같습니다.","[ML⁻¹T⁻¹] = [FL⁻²T].":"점성계수는 질량 길이 시간 표기와 힘 길이 시간 표기로 모두 나타낼 수 있는 차원입니다.","c = √(kRT). 온도의 함수이며 압력의 함수가 아니다.":"이상기체의 음속은 절대온도의 제곱근에 비례해 정해지고 압력과는 무관합니다.","cosθ = P/S. 예) 피상 10 kVA, 무효 6 kVar → P = √(10² − 6²) = 8 kW.":"역률은 유효전력을 피상전력으로 나눈 값이며 피상 10 kVA, 무효 6 kVar이면 유효는 8 kW입니다.","e = N·ΔΦ/Δt = M·ΔI/Δt (크기). 코일 감은 수 N, 자속 변화 ΔΦ, 상호인덕턴스 M.":"유도기전력의 크기는 코일 감은 수에 시간당 자속 변화를 곱한 값이며 상호인덕턴스와 전류 변화로도 나타냅니다.","f = 64/Re. 레이놀즈수만의 함수다.":"층류에서는 마찰손실계수가 64를 레이놀즈수로 나눈 값이라 레이놀즈수만으로 정해집니다.","h = 128μLQ ÷ (πγD⁴). 유량이 일정하면 지름의 4승에 반비례한다.":"층류 손실수두는 유량이 같으면 지름의 4승에 반비례해 관이 굵을수록 급격히 줄어듭니다.","h = 2σcosθ ÷ (γb). b는 판 사이 간격. 간격이 좁을수록 높이 올라간다(문항에 간격 조건 누락, 정답은 약 0.3 cm).":"평행한 두 유리판 사이에서는 판 간격이 좁을수록 물이 높이 오르며, 문항에 간격 조건이 빠져 있습니다.","h = 4σcosθ ÷ (γd). σ 표면장력, θ 접촉각, d 관 지름.":"모세관에서 물이 오르는 높이는 표면장력과 접촉각 코사인에 비례하고 단위중량과 관 지름에 반비례합니다.","h = 4σcosθ ÷ (γd) − Pa/γ.":"대기압을 고려하면 상승높이에서 대기압을 단위중량으로 나눈 값을 뺍니다.","h = K(V₁ − V₂)²/2g, 이론 K = 1.":"급확대 손실수두는 확대 전후 유속 차의 제곱에 비례하며 이론 손실계수는 1입니다.","h_f = 8fLQ² ÷ (π²gD⁵). 지름 D는 5승에 반비례.":"유량으로 바꿔 쓴 식에서 손실수두는 유량 제곱에 비례하고 지름의 5승에 반비례합니다.","h_f = f·(L/D)·(V²/2g). 마찰손실수두는 관의 길이 L, 마찰손실계수 f, 유속의 제곱 V²에 비례하고 관경 D, 중력가속도 g에 반비례한다.":"마찰손실수두는 관 길이, 마찰손실계수, 유속 제곱에 비례하고 관경과 중력가속도에 반비례합니다.","m²/s. CGS는 stokes(St) = cm²/s. 1 St = 10⁻⁴ m²/s. 점성계수와 동점성계수는 단위가 다르다.":"동점성계수의 단위는 m²/s이고, CGS 단위 stokes는 10⁻⁴ m²/s이며 점성계수 단위와 다릅니다.","pH 6~9, 설계값 ±0.4 이내(2023 기출 당시 수성막포 6.0 이상 8.5 이하를 옳은 선지로 출제).":"포 약제의 pH는 6에서 9 사이이고 설계값에서 ±0.4 이내여야 합니다.","v = 1/ρ. 단위 질량이 차지하는 체적.":"비체적은 밀도의 역수이므로 질량 단위당 차지하는 부피를 나타냅니다.","v = Vm·sin ωt 의 실효값 V = Vm/√2. 평균값(반주기) = 2Vm/π.":"정현파의 실효값은 최댓값을 2의 제곱근으로 나눈 값이고 반주기 평균값은 최댓값의 2/π배입니다.","v = √2·100·sin(500t), R 40 Ω, C 100 μF, L 100 mH: X_L = 50 Ω, X_C = 20 Ω, Z = √(40² + 30²) = 50 Ω → I = 100 ÷ 50 = 2 A.":"ω가 500이라 X_L은 50 Ω, X_C는 20 Ω이고 Z는 50 Ω이므로 전류는 100 V를 50 Ω으로 나눈 2 A입니다.","γ = ρg. 물의 γ = 9,800 N/m³ = 1,000 kgf/m³.":"단위중량은 밀도에 중력가속도를 곱한 값이라 물은 9,800 N/m³이 됩니다.","θ = tan⁻¹(X/R). 역률 cosθ = R/|Z|.":"임피던스 각은 리액턴스를 저항으로 나눈 값의 역탄젠트이고 역률은 저항을 임피던스 크기로 나눈 값입니다.","μ = ν × ρ. 예) ν 0.002 m²/s, 비중 1.1(ρ 1,100) → 2.2 N·s/m².":"SI에서는 점성계수가 동점성계수와 밀도의 곱이므로 이 예는 2.2 N·s/m²가 됩니다.","ν(St) = μ(P) ÷ 밀도(g/cm³). 예) 0.8 P, 비중 1.1 → 0.8 ÷ 1.1 = 0.727 St.":"CGS에서 동점성계수는 점성계수 poise를 밀도로 나누며 이 예는 0.727 St입니다.","ν = μ/ρ. 점성계수를 밀도로 나눈 값이다(유속으로 나누는 것이 아니다).":"동점성계수는 점성계수를 밀도로 나눈 값이며, 유속으로 나누는 값이 아닙니다.","ρ₁A₁V₁ = ρ₂A₂V₂. 비압축성이면 Q = AV = 일정, A₁V₁ = A₂V₂.":"질량보존에 따라 단면마다 밀도·단면적·유속의 곱이 같고, 비압축성이면 유량이 일정합니다.","τ = L/R. 전류·전압 응답 y(t) = y(∞) + [y(0) − y(∞)]·e^(−t/τ).":"RL 회로의 시정수는 인덕턴스를 저항으로 나눈 값이고 응답은 최종값을 향해 지수함수로 수렴합니다.","ω를 읽는다(v = √2·V·sin(ωt)에서 계수) → X_L, X_C → Z → I = V/Z. 실효값 V는 √2를 뺀 값.":"전압식의 ωt 계수에서 ω를 읽어 리액턴스와 임피던스를 구해 전류를 계산하며 실효값은 √2를 뺀 값입니다.","가압식은 최고사용압력의 1.8배 이하, 축압식은 용기 내압시험압력의 0.8배 이하에서 작동(2022 기출 당시 가압식 2.5배를 틀린 선지로 출제).":"안전밸브는 가압식이 최고사용압력의 1.8배 이하, 축압식이 내압시험압력의 0.8배 이하에서 열려야 합니다.","가압용 질소: 소화약제 1 ㎏마다 40 L(35 ℃, 1기압 환산) 이상. 축압용 질소: 1 ㎏마다 10 L 이상. 이산화탄소: 소화약제 1 ㎏에 20 g에 배관 청소에 필요한 양을 가산한 양 이상.":"질소 가압용은 약제 1 ㎏마다 40 L(35 ℃, 1기압), 축압용은 10 L 이상이며 이산화탄소는 1 ㎏에 20 g과 청소량을 더합니다.","가연성금속에 의한 화재. 금속이 괴상이 아니라 고운 분말이나 가는 선 형태로 존재하면 위험성이 더 커진다.":"금속화재는 가연성 금속이 타는 불이며 금속이 분말이나 가는 선이면 표면적이 커져 더 위험합니다.","가장 큰 방호구역에 대하여 산출한 양 이상으로 한다(별도 독립방식 대상 아닌 경우).":"방호구역이 둘 이상이면 가장 큰 구역 기준으로 산출한 약제량 이상을 두며 별도 독립방식은 예외입니다.","각 θ의 최대 수직상승높이 H = (V·sinθ)² ÷ 2g. 예) 9.8 m/s, 45° → (6.93)² ÷ 19.6 = 2.45 m. 관 지름은 계산에 쓰이지 않는다.":"비스듬히 쏜 물줄기가 오르는 높이는 수직 방향 속도 성분으로 정해지므로 관 지름은 쓰이지 않습니다.","각속도 ω = 2πf. 위상 R: 전압과 전류 동상. L: 전류가 전압보다 90° 뒤진다. C: 전류가 전압보다 90° 앞선다.":"저항은 전압과 전류가 동상이고 코일은 전류가 90° 뒤지며 콘덴서는 전류가 90° 앞섭니다.","각 출력의 논리식(자기유지 + 정지 조건 + 인터록)을 쓴다":"각 출력마다 자기유지, 정지 조건, 인터록을 넣은 논리식을 먼저 세웁니다.","감지기 회로는 교차회로방식으로 설치한다.":"감지기 회로를 교차회로방식으로 하면 두 계통이 모두 감지해야 방출되어 오작동 방출을 막습니다.","강화액(수계 약제)을 쓸 수 없다.":"금속화재에는 물을 쓰는 수계 약제인 강화액이 적응하지 않습니다.","강화액을 사용하면 냉각 효과로 소화할 수 있다.":"주방화재에 강화액을 쓰면 냉각 효과로 불을 끌 수 있습니다.","같은 용량 n개 직렬은 C/n. 예) 300 μF 3개 직렬 = 100 μF.":"같은 용량의 콘덴서 n개를 직렬로 이으면 개수로 나눈 값이 되어 300 μF 3개는 100 μF입니다.","같은 유체로 이어진 같은 높이의 압력은 같다는 원리로 압력차를 구한다. P₁ − P₂ = (γ액 − γ물)h.":"U자관에서는 같은 높이의 같은 유체 안 압력이 같다는 원리로 두 지점의 압력차를 구합니다.","개구부에 자동폐쇄장치가 없으면 개구부 면적 1 ㎡당 10 ㎏을 가산한다. 개구부 면적은 방호구역 전체 표면적의 3 % 이하.":"심부화재에서 자동폐쇄장치가 없는 개구부는 1 ㎡당 10 ㎏을 더하며 면적은 전체 표면적의 3 % 이하입니다.","개구부에 자동폐쇄장치를 설치하지 않은 경우: 개구부면적 1 ㎡당 5 ㎏을 가산한다. 개구부 면적은 방호구역 전체 표면적의 3 % 이하.":"자동폐쇄장치가 없는 개구부는 1 ㎡당 5 ㎏을 더하며 개구부 면적은 전체 표면적의 3 % 이하여야 합니다.","계산한 양에 고압식은 1.4, 저압식은 1.1을 곱한 양 이상.":"국소방출은 계산한 양에 고압식이면 1.4, 저압식이면 1.1을 곱한 양 이상을 둡니다.","고압식 1.5 이상 1.9 이하, 저압식 1.1 이상 1.4 이하.":"용기 내용적을 약제 중량으로 나눈 충전비는 고압식 1.5~1.9, 저압식 1.1~1.4로 정해져 있습니다.","고압식 16.5 ㎫ 이상, 저압식 3.75 ㎫ 이상의 압력에 견딜 것. 배관부속 최소사용설계압력: 고압식 1차측 9.5 ㎫, 고압식 2차측과 저압식 4.5 ㎫.":"동관은 고압식 16.5 ㎫ 이상, 저압식 3.75 ㎫ 이상의 압력에 견뎌야 하며 부속은 방식별 최소사용설계압력이 정해집니다.","고압식 25 ㎫ 이상, 저압식 3.5 ㎫ 이상.":"내압시험압력은 고압식 25 ㎫ 이상, 저압식 3.5 ㎫ 이상입니다.","고전압 결선에 적합하다(상전압이 선간전압의 1/√3).":"Y-Y 결선은 상전압이 선간전압의 1/√3이라 고전압 결선에 알맞습니다.","고체에어로졸화합물의 연소과정으로 생성된 직경 10 마이크로미터 이하의 고체 입자와 기체 상태 물질의 혼합물.":"고체에어로졸은 화합물이 연소하며 생기는 직경 10 마이크로미터 이하 고체 입자와 기체의 혼합물입니다.","공기 중 산소 21 vol%, 질소 79 vol%. 산소 1 mol에 동반하는 질소 = 79/21 = 3.76 mol.":"공기는 산소 21, 질소 79 부피비라서 산소 1 mol당 질소 3.76 mol이 함께 따라옵니다.","공동현상의 영향: 소음과 진동, 양정·효율 저하, 임펠러 침식(깃 손상).":"공동현상이 나면 소음과 진동이 생기고 양정과 효율이 떨어지며 임펠러 깃이 침식됩니다.","과산화물질, 가연성물질 등의 혼합물로서 화재를 소화하는 비전도성의 미세입자인 에어로졸을 만드는 고체화합물.":"고체에어로졸화합물은 연소해 비전도성 미세입자인 에어로졸을 만들어 소화하는 고체 화합물입니다.","관 마찰손실(직선관에서 일어나는 마찰에 의한 손실).":"주손실은 직선관을 흐르는 동안 관벽 마찰로 생기는 손실입니다.","관 안 유체의 속도가 급변하여 압력이 급상승·하강하는 현상.":"수격작용은 관 속 유체의 속도가 갑자기 바뀌어 압력이 급하게 오르내리는 현상입니다.","광전식 공기흡입형 감지기, 아날로그 방식의 광전식 스포트형 감지기 또는 적응성이 있다고 인정된 감지기.":"감지기는 광전식 공기흡입형이나 아날로그 광전식 스포트형 등 적응성이 인정된 것을 씁니다.","금속화재의 주된 소화약제는 건조사(마른모래), 팽창질석·팽창진주암, D급 분말 등이다. 이산화탄소·강화액·K급 약제는 적응성이 없다.":"금속화재에는 건조사, 팽창질석·팽창진주암, D급 분말을 쓰고 이산화탄소·강화액·K급 약제는 맞지 않습니다.","기동 시 1분 이내에 설계밀도의 95 % 이상을 방호구역에 균일하게 방출한다. 방출 개시 후 1분 이상 경보를 계속한다.":"기동하면 1분 안에 설계밀도의 95 % 이상을 고르게 방출하고 방출 개시 후 1분 이상 경보를 울립니다.","기본파 100·30/2·cos60° = 750, 3고조파는 위상차 90°라 0, 5고조파 10·5/2 = 25 (cos 항은 sin으로 환산 후 위상 비교) → 합 775 W.":"기본파 750, 3고조파 0, 5고조파 25를 더해 합계 775 W가 되며 3고조파는 위상차 90°라 0입니다.","내경 0.5 m, 400 m, 손실수두 10 m, 정답 0.517 m³/s는 f ≈ 0.035일 때 나온다(문항에 f 조건 누락, 추정). 순서는 V = √(h·2gD ÷ fL) → Q = AV.":"손실수두에서 유속을 먼저 구한 뒤 단면적을 곱해 유량을 구하며 f 조건이 문항에 빠져 있습니다.","내경 200 mm, 3 m/s, 80 m, 정답 7.71 m는 f ≈ 0.042일 때 나온다(문항에 f 조건 누락, 추정).":"손실수두를 맞추는 정답 7.71 m는 f를 약 0.042로 가정할 때 나오므로 조건이 문항에서 누락됐습니다.","내압시험압력의 0.64배~0.8배에서 작동하는 안전밸브와 0.8배~내압시험압력에서 작동하는 봉판을 설치.":"저압식은 안전밸브가 내압시험압력 0.64배~0.8배에서, 봉판이 0.8배~내압시험압력에서 작동하도록 이중으로 둡니다.","냉각(주), 질식(수증기 팽창), 유화·희석(수용성 액체). 무상 방사로 전기화재·유류화재에 활용한다.":"물은 주로 냉각으로 끄고 수증기 팽창으로 질식시키며 수용성 액체에는 유화와 희석 효과를 냅니다.","냉각과 알칼리금속염(칼륨염)의 부촉매(억제) 작용이다. 화염과 접촉하면 질소가 발생하여 질식소화한다는 설명은 맞지 않다.":"강화액은 냉각과 칼륨염의 부촉매 작용으로 끄며, 화염에서 질소가 생겨 질식시킨다는 설명은 틀립니다.","농형 유도전동기 Y-Δ 기동: 기동전류는 Δ결선으로 직접 기동한 경우의 1/3. Δ → Y 변환 시 선전류 비 I_Y/I_Δ = 1/3 (임피던스가 같을 때).":"농형 유도전동기를 Y-Δ로 기동하면 기동전류가 Δ결선 직접 기동의 1/3로 줄어듭니다.","농형은 Y-Δ 기동, 기동보상기법, 리액터 기동. 권선형은 2차 회로에 저항을 삽입해 기동전류를 제한한다(기동보상기법이 아님).":"농형은 Y-Δ, 기동보상기, 리액터 기동으로 전류를 줄이고 권선형은 2차 회로에 저항을 넣어 줄입니다.","뉴턴 유체(전단응력이 속도경사에 비례), 비뉴턴 유체, 이상유체(비점성·비압축성), 실제유체(점성 있음).":"뉴턴 유체는 전단응력이 속도경사에 비례하고, 이상유체는 점성이 없고 압축되지 않는 가상의 유체입니다.","다단펌프의 비속도는 1단 양정(H/단수)으로 계산한다.":"다단펌프는 전체 양정이 아니라 한 단이 내는 양정을 단수로 나눠 비속도를 계산합니다.","단백포(단백질 가수분해물), 합성계면활성제포, 수성막포(합성계면활성제 중 기름 표면에 수성막을 형성), 알코올형포(수용성 용제 소화용).":"포 약제는 단백포, 합성계면활성제포, 수성막포, 알코올형포로 나눕니다.","단상변압기 2대로 3상 전력을 얻는 방식. 이용률 √3/2 = 86.6 %, 출력비(Δ결선 대비) 1/√3 = 57.7 %. 출력 P_V = √3·P₁ (P₁은 변압기 1대 용량). Δ결선 변압기 3대 출력(3P₁) 대비 57.7 %.":"V결선은 단상변압기 2대로 3상 전력을 얻으며 이용률이 86.6 %, Δ결선 대비 출력비가 57.7 %입니다.","단상 유도전동기: 기동권선에 직렬로 콘덴서를 연결하여 주권선과 기동권선 사이에 위상차를 만들어 기동한다.":"콘덴서 기동형은 기동권선과 직렬로 콘덴서를 달아 두 권선 사이에 위상차를 만들어 기동합니다.","단상 유도전동기: 병렬로 연결된 주권선과 보조권선이 회전자계를 만들어 기동한다.":"분상 기동형은 병렬로 연결된 주권선과 보조권선이 회전자계를 만들어 단상 유도전동기를 돌립니다.","단위 체적당 질량. 물은 4℃에서 1,000 kg/m³ = 1 g/cm³(최대).":"밀도는 단위 부피의 질량이며, 물은 4℃에서 밀도가 가장 커서 1,000 kg/m³입니다.","도체는 온도가 오르면 저항이 증가한다. 절연체와 반도체는 온도가 오르면 저항이 감소한다.":"도체는 온도가 오르면 저항이 늘고 절연체와 반도체는 반대로 저항이 줄어듭니다.","도체에 전류를 흘릴 때 자기장 속에서 받는 힘: 플레밍의 왼손 법칙(전동기). 엄지 힘, 검지 자계, 중지 전류.":"전류가 흐르는 도체가 자기장 속에서 받는 힘의 방향은 플레밍의 왼손 법칙으로 찾고 전동기에 해당합니다.","도체에 큰 전류를 흘리면 전류 자신이 만드는 자기력으로 도체가 수축하는 현상.":"핀치 효과는 큰 전류가 만드는 자기력이 도체를 안쪽으로 조여 수축시키는 현상입니다.","도체의 운동으로 생기는 기전력: 플레밍의 오른손 법칙(발전기). 렌츠의 법칙은 유도기전력이 자속 변화를 방해하는 방향.":"도체 운동으로 생기는 기전력의 방향은 오른손 법칙으로 찾고, 렌츠의 법칙은 유도기전력이 자속 변화를 방해한다는 것입니다.","동수경사선(HGL): 압력수두와 위치수두의 합을 연결한 선. 에너지선(EGL): 여기에 속도수두를 더한 선.":"동수경사선은 압력수두와 위치수두의 합을, 에너지선은 여기에 속도수두까지 더해 이은 선입니다.","동일 인덕턴스 2개 직렬(상호결합 없음) 합성 인덕턴스는 2배.":"상호결합이 없으면 같은 인덕턴스 2개를 직렬로 이은 합성 인덕턴스는 2배가 됩니다.","동일 집합관에 접속되는 저장용기는 동일한 내용적을 가진 것으로 충전량과 충전압력이 같도록 한다.":"같은 집합관에 연결되는 용기는 내용적이 같고 충전량과 충전압력도 같아야 합니다.","동종 금속 도선의 두 점 사이에 온도차를 주고 전류를 흘리면 줄열 외에 열의 발생 또는 흡수가 일어나는 현상.":"톰슨 효과는 같은 금속 도선 두 점에 온도차를 주고 전류를 흘리면 줄열 외에 열이 생기거나 흡수되는 현상입니다.","두 출력의 NOT을 서로의 AND 입력에 되먹임하여 한쪽이 동작하면 다른 쪽은 동작하지 못하게 하는 회로.":"인터록은 두 출력의 NOT을 서로의 AND 입력에 되돌려 한쪽이 동작하면 다른 쪽이 동작하지 못하게 합니다.","등류: 유동 특성이 장소(거리)에 따라 변하지 않는 흐름(∂U/∂x = 0). 부등류: 장소에 따라 변하는 흐름(∂U/∂x ≠ 0).":"등류는 위치가 달라져도 유동 특성이 같은 흐름이고, 부등류는 위치마다 달라지는 흐름입니다.","레이놀즈수와 상대조도(e/D)의 함수다.":"난류의 마찰손실계수는 레이놀즈수와 관 표면의 상대조도에 함께 좌우됩니다.","마주 보는 변 저항의 곱이 같으면(R₁R₄ = R₂R₃) 가운데 저항에 전류가 흐르지 않는다. 가운데 저항은 무시하고 합성한다.":"마주 보는 변의 저항 곱이 같으면 브리지가 평형이라 가운데 저항에 전류가 흐르지 않아 무시하고 합성합니다.","마찰손실은 미소손실이 아니다.":"관 마찰손실은 주손실에 해당하므로 미소손실로 분류하지 않습니다.","메타인산(HPO₃)은 숯 표면에 유리상 피막을 만들어 산소를 차단하는 방진효과가 있다.":"메타인산은 숯 표면에 유리 같은 피막을 만들어 산소를 막는 방진효과를 냅니다.","무효전력 Q = √3·(W₁ − W₂). 피상전력 S = 2√(W₁² + W₂² − W₁W₂). 역률 cosθ = (W₁ + W₂) ÷ (2√(W₁² + W₂² − W₁W₂)).":"무효전력은 두 지시값의 차에 3의 제곱근을 곱하고 역률은 유효전력을 피상전력으로 나눈 값입니다.","물과 유리의 접촉각은 거의 0°(cosθ≈1)라 물은 올라가고, 수은은 접촉각이 커서 내려간다.":"접촉각이 거의 0도인 물은 유리를 적셔 올라가고, 접촉각이 큰 수은은 유리를 적시지 못해 내려갑니다.","물은 극성분자이며 분자 사이에 수소결합을 한다.":"물 분자는 전하가 한쪽으로 치우친 극성이라 이웃 분자와 수소결합으로 서로 끌립니다.","물은 부적합하다(봉상 주수 시 유류 확산). 냉각이 주된 효과이며 부촉매 효과가 아니다.":"유류화재에 물을 봉상으로 뿌리면 기름이 퍼지므로 부적합하고, 물의 주 효과는 부촉매가 아닌 냉각입니다.","물의 비열 1 cal/g·℃ = 1 kcal/kg·℃ = 4.18 kJ/kg·K.":"물의 비열은 단위를 바꿔도 같은 값이라 cal 단위의 1이 kJ 단위로는 4.18에 해당합니다.","물의 융해열(얼음 → 물) 약 79.7 cal/g(약 80 kcal/kg).":"얼음이 물로 바뀔 때 필요한 융해열은 약 79.7 cal/g입니다.","물의 증발잠열(100℃) 약 539 cal/g = 539 kcal/kg = 2,253 kJ/kg.":"증발잠열은 100℃에서 약 539 cal/g이며 kcal/kg이나 kJ/kg 단위로도 씁니다.","물질계가 흡수하는 열량과 절대온도의 비로 정의한다(dS = δQ/T). 무질서 또는 에너지의 분산 정도를 나타내는 상태함수다.":"엔트로피는 흡수한 열을 절대온도로 나눈 값으로 정의하며 무질서한 정도를 나타내는 상태함수입니다.","미소손실 일반식: h = K·V²/2g (K 손실계수).":"미소손실은 손실계수 K에 속도수두를 곱한 값으로 구합니다.","발포배율이 커지면 포 막이 얇아져 환원시간이 짧아진다. 포의 막이 두꺼울수록 환원시간은 길어진다. 발포배율이 작은 포는 포의 직경이 작고 막이 두껍다.":"발포배율이 커지면 포 막이 얇아져 환원시간이 짧아지고, 배율이 작은 포는 직경이 작고 막이 두껍습니다.","발포 전 포수용액 용량의 25 %가 거품에서 환원되는 데 걸리는 시간. 환원시간이 길수록 양호한 포소화약제다.":"환원시간은 포수용액의 25 %가 거품에서 물로 돌아오는 시간이며 길수록 포가 오래 유지됩니다.","방지(보충): 회전수 변경, 임펠러 지름 조정, 풍량·유량 정격 범위 유지.":"회전수를 바꾸거나 임펠러 지름을 조정하고 정격 범위를 지켜 운전하는 보충 방지책입니다.","방지(보충): 흡입관경을 크게, 흡입관 길이와 부속을 줄여 흡입손실을 줄인다. 유속과 회전수를 낮춘다. 양흡입 펌프 사용. 두 대 이상 직렬 운전 또는 흡입측 가압.":"흡입관을 굵고 짧게 하고 유속과 회전수를 낮추며 양흡입 펌프를 쓰는 등의 보충 방지책입니다.","방지: H-Q 곡선이 우하향 구배 특성을 갖는 펌프를 사용한다.":"H-Q 곡선이 우하향하는 특성의 펌프를 쓰면 서징을 막을 수 있습니다.","방지: 계획토출량보다 현저히 벗어난 범위로 운전하는 것을 피한다.":"계획토출량에서 크게 벗어난 범위로 운전하지 않는 것이 공동현상 방지책입니다.","방지: 관경을 크게 하여 유속을 줄인다. 플라이휠, 에어챔버, 서지탱크, 완폐식 체크밸브를 설치한다.":"관경을 키워 유속을 줄이고 플라이휠, 에어챔버, 서지탱크, 완폐식 체크밸브를 달아 수격작용을 줄입니다.","방지: 바이패스관을 사용하여 운전점이 H-Q 곡선의 우하향 구배 범위 안에 있도록 한다.":"바이패스관으로 운전점이 곡선의 우하향 범위 안에 놓이게 하는 서징 방지책입니다.","방지: 배관 안에 수조 또는 기체 상태인 부분이 존재하지 않도록 한다.":"배관 안에 수조나 기체가 차는 부분이 없게 해 서징이 생기지 않게 합니다.","방지: 유량조절밸브는 흡입측이 아니라 펌프 토출측(펌프에 가까이)에 설치한다.":"유량조절밸브를 흡입측이 아니라 펌프 가까운 토출측에 두는 서징 방지책입니다.","방지: 펌프 설치 위치를 가능한 낮게 한다(흡입양정을 작게).":"펌프를 낮게 설치해 흡입양정을 줄이면 흡입 쪽 압력이 높아져 공동현상을 막습니다.","방지: 흡입수조의 형상과 치수를 과도한 편류·와류가 생기지 않게 한다.":"흡입수조의 모양과 치수를 정해 쏠린 흐름과 와류가 지나치게 생기지 않게 하는 방지책입니다.","방출경로 배관의 내용적 비율이 제조업체 설계기준 값 이상이면 해당 방호구역은 별도 독립방식으로 한다.":"방출경로 배관 내용적 비율이 설계기준 이상인 구역은 다른 구역과 묶지 않고 독립방식으로 설치합니다.","방호공간(방호대상물 각 부분으로부터 0.6 m 거리로 둘러싸인 공간) 체적 1 ㎥당 Q = 8 − 6a/A (kg/㎥). a는 방호대상물 주위 벽 면적의 합계, A는 방호공간 벽 면적의 합계.":"그 외 국소방출은 방호공간 ㎥당 약제량을 8에서 6에 주위 벽 면적비를 곱한 값을 뺀 값으로 구합니다.","방호공간 내 규정된 시험조건의 화재를 소화하는 데 필요한 단위체적(㎥)당 고체에어로졸화합물의 질량(g). 설계밀도 = 소화밀도 × 안전계수.":"소화밀도는 규정 화재를 끄는 데 필요한 ㎥당 화합물 질량이며 설계밀도는 여기에 안전계수를 곱한 값입니다.","방호구역마다, 출입구 부근 등 피난이 쉬운 곳, 조작부는 바닥에서 0.8 m 이상 1.5 m 이하, 방출지연스위치 설치.":"수동식 기동장치는 방호구역마다 피난이 쉬운 출입구 부근에 두고 조작부는 0.8 m 이상 1.5 m 이하에 방출지연스위치와 함께 답니다.","방호구역 외(방호구역 내라면 피난구 부근), 온도 40 ℃ 이하이고 온도변화가 작은 곳, 직사광선·빗물 침투 우려가 없는 곳, 방화문으로 방화구획 된 실, 용기 간 간격 3 ㎝ 이상.":"분말 저장용기는 방호구역 밖 40 ℃ 이하이고 직사광선과 빗물이 닿지 않는 방화구획 실에 용기 간 간격 3 ㎝ 이상으로 둡니다.","방호구역 외의 장소(방호구역 내라면 피난구 부근), 온도 40 ℃ 이하이고 온도변화가 작은 곳, 직사광선·빗물 침투 우려가 없는 곳, 방화문으로 구획된 실. 용기 간격 3 ㎝ 이상.":"이산화탄소 저장용기는 방호구역 밖 40 ℃ 이하, 직사광선·빗물이 닿지 않는 방화문 구획 실에 용기 간격 3 ㎝ 이상으로 둡니다.","방호구역의 각 부분에서 하나의 음향장치까지 수평거리 25 m 이하, 1 m 거리에서 90 dB 이상, 정격전압 80 %에서 음을 발할 것.":"음향장치는 수평거리 25 m 이하로 두고 1 m 거리에서 90 dB 이상, 정격전압 80 %에서도 소리가 나야 합니다.","방호구역 체적 1 ㎥당 약제량(종별 표) + 자동폐쇄장치가 없는 개구부는 면적당 가산량. 표는 원문 이미지로 텍스트 미확인.":"전역방출 약제량은 방호구역 체적 1 ㎥당 종별 양에 자동폐쇄장치 없는 개구부의 면적당 가산량을 더합니다.","배관은 전용으로 한다. 강관은 압력배관용탄소강관(KS D 3562) 스케줄 80 이상(저압식 스케줄 40 이상). 호칭구경 20 ㎜ 이하는 스케줄 40 이상 가능.":"배관은 전용이며 강관은 압력배관용탄소강관 스케줄 80 이상, 저압식은 스케줄 40 이상이고 호칭구경 20 ㎜ 이하는 40 이상도 됩니다.","변압기 1대 고장 시 전력공급이 불가능하다.":"Y-Δ 결선은 변압기 1대가 고장 나면 전력 공급이 되지 않습니다.","부하가 복소 임피던스로 조정 가능하면 Z_L = Zs* (켤레복소수)일 때 최대 전력.":"부하 임피던스를 복소수로 조정할 수 있으면 전원 임피던스의 켤레복소수일 때 최대 전력이 전달됩니다.","분말소화설비는 제1종~제4종 분말을 쓰되, 차고 또는 주차장에 설치하는 분말소화설비의 소화약제는 제3종 분말로 해야 한다.":"차고나 주차장에 두는 분말소화설비는 제3종 분말을 써야 하며 일반 설비는 제1종부터 제4종까지 씁니다.","분말은 방습가공을 한 나트륨 또는 칼륨의 중탄산염, 인산염류, 황산염류 등 방염성 염류로서 형식승인 기준에 적합해야 한다.":"분말은 방습가공한 나트륨이나 칼륨 중탄산염, 인산염류, 황산염류 같은 방염성 염류여야 합니다.","분사헤드 설치제외 장소: 방재실·제어실 등 사람이 상시 근무하는 장소, 니트로셀룰로스·셀룰로이드제품 등 자기연소성물질 저장·취급 장소, 나트륨·칼륨·칼슘 등 활성금속물질 저장·취급 장소, 전시장 등 다수인이 출입·통행하는 통로·전시실.":"방재실처럼 사람이 상시 근무하는 곳, 자기연소성물질·활성금속물질 저장소, 다수인이 지나는 통로와 전시실에는 분사헤드를 달지 않습니다.","불소, 염소, 브롬 또는 요오드 중 하나 이상의 원소를 포함하는 유기화합물을 기본성분으로 하는 소화약제.":"할로겐화합물소화약제는 불소, 염소, 브롬, 요오드 중 하나 이상을 포함한 유기화합물이 기본성분입니다.","불연성 가스, 무색·무취, 공기에 대한 비중 약 1.5(44/29).":"이산화탄소는 타지 않는 무색·무취 기체이며 공기보다 무거워 비중이 약 1.5입니다.","불활성기체(IG-01, IG-100, IG-541, IG-55)의 최대허용 설계농도는 43 %(보충, 원문 표 이미지로 텍스트 미확인).":"불활성기체 IG-01, IG-100, IG-541, IG-55의 최대허용 설계농도는 43 %입니다.","비상전원은 20분 이상 작동. 자동폐쇄장치, 배출설비(지하층·무창층·밀폐된 거실), 과압배출구, 부취발생기(2024.8.1. 신설)를 설치한다.":"비상전원은 20분간 가동되어야 하며 과압배출구와 부취발생기(2024.8.1. 신설) 같은 부대설비도 필요합니다.","비속도가 작으면 고양정·소유량(원심), 크면 저양정·대유량(축류) 쪽이다.":"비속도가 작으면 원심형처럼 고양정·소유량이고, 크면 축류형처럼 저양정·대유량 펌프입니다.","비정상류와 압축성 유체의 흐름은 적용조건이 아니다.":"시간에 따라 변하는 비정상류나 압축성 유체에는 베르누이 방정식을 쓸 수 없습니다.","비정현파 실효값 = √(각 고조파 실효값의 제곱합). 예) 50, 30, 10 V → √(2500 + 900 + 100) = √3500 ≈ 59 V.":"비정현파 실효값은 각 고조파 실효값을 제곱해 더한 합의 제곱근이며 이 예는 약 59 V입니다.","비정현파 평균전력 = 같은 차수 고조파끼리 (Vm·Im/2)·cos(θv − θi)를 모두 더한 값. 다른 차수의 곱은 평균전력에 기여하지 않는다.":"비정현파 평균전력은 같은 차수 고조파끼리 전력을 구해 더하고 다른 차수의 곱은 평균전력에 기여하지 않습니다.","비중 = 공기 중 무게 ÷ (공기 중 무게 − 수중 무게). 예) 2 kg, 0.5 kg → 2 ÷ 1.5 = 1.33.":"공기 중 무게를 수중에서 줄어든 무게로 나누는 식이며 이 예는 1.33이 됩니다.","사람이 상주하는 곳으로 최대허용 설계농도를 초과하는 장소, 소화성능이 인정되지 않는 위험물을 저장·보관·사용하는 장소.":"사람이 있는 곳으로 최대허용 설계농도를 넘는 장소와 소화성능이 인정되지 않는 위험물 취급 장소에는 설치하지 않습니다.","사류·상류·한계류는 프루드수로 가른다. 레이놀즈수로 알 수 있는 흐름은 층류·난류·천이류이다.":"상류인지 사류인지는 프루드수로, 층류인지 난류인지는 레이놀즈수로 판별합니다.","사용하한온도보다 2.5 ℃ 이하.":"유동점은 포 약제가 흐르는 최저 온도이며 사용하한온도보다 2.5 ℃ 이하여야 합니다.","사용할 수 없다(금속이 이산화탄소와 반응). 소화효과는 질식·냉각이다.":"금속은 이산화탄소와 반응하므로 금속분화재에는 쓸 수 없으며 소화효과는 질식과 냉각입니다.","산소 농도 21 vol%, 소화에 필요한 산소 한계농도는 약 15%(CO₂ 방출 시 약 28.6% 이상 CO₂ 필요).":"공기 중 산소는 21 vol%이고 소화되려면 산소 농도가 약 15%까지 내려가야 합니다.","산화성 물질, 자기반응성 금속, 금속 수소화물, 자동 열분해를 하는 화학물질 등을 포함한 화재와 폭발성 물질이 존재할 가능성이 있는 장소.":"산화성 물질, 자기반응성 금속, 금속 수소화물 등과 폭발성 물질이 있을 수 있는 곳에는 설치하지 않습니다.","삼중점 -56.7 ℃(5.2 atm), 임계온도 31.1 ℃, 승화점 -78.5 ℃.":"이산화탄소는 임계온도 31.1 ℃ 이하에서 액화할 수 있고 대기압에서는 -78.5 ℃에서 승화합니다.","상류(常流): 프루드수 Fr < 1. 사류(射流): Fr > 1. 한계류: Fr = 1. 프루드수 Fr = V/√(gh).":"프루드수가 1보다 작으면 상류, 크면 사류, 1이면 한계류이며 유속과 파의 전파 속도를 견준 값입니다.","상온·표준상태에서 물의 비열은 1 cal/g·℃로 소화약제 후보 중 가장 크다. 사염화탄소 약 0.2, 파라핀 약 0.5~0.7, 가스계 약제는 훨씬 작다.":"물의 비열은 소화약제 후보 가운데 가장 커서 같은 질량으로 더 많은 열을 흡수합니다.","서고 80 ㎥, 개구부에 자동개폐장치가 있음 → 2.0 × 80 = 160 kg(가산 없음).":"서고 80 ㎥는 개구부에 자동개폐장치가 있어 가산 없이 2.0 × 80으로 160 kg입니다.","서로 교차하지 않는다. 자계의 방향은 자기력선 위 한 점에서의 접선 방향. 밀도는 자계의 세기와 같다. 자석 외부는 N극에서 나와 S극으로 들어가고 내부는 S극에서 N극으로 향한다.":"자기력선은 서로 교차하지 않고 자석 밖에서는 N극에서 S극으로, 안에서는 S극에서 N극으로 향합니다.","서로 다른 금속으로 된 폐회로에 온도를 일정하게 두고 직류 전류를 흘리면 접합부에서 열의 발생 또는 흡수가 일어나는 현상.":"펠티에 효과는 서로 다른 금속 회로에 직류를 흘리면 접합부에서 열이 발생하거나 흡수되는 현상입니다.","선간전압 V_l = V_p, 선전류 I_l = √3·I_p (30° 뒤짐).":"Δ결선은 선간전압이 상전압과 같고 선전류가 상전류의 3의 제곱근 배이며 30° 뒤처집니다.","선간전압 V_l = √3·V_p (30° 앞섬), 선전류 I_l = I_p.":"Y결선은 선간전압이 상전압의 3의 제곱근 배이고 30° 앞서며 선전류는 상전류와 같습니다.","설계값 ±30 % 이내이고 200 ㎟/s 이하(단백포 400, 알코올형 3,500 ㎟/s 이하).":"점도 한도는 설계값 ±30 % 이내이면서 200 ㎟/s 이하이고 단백포 400, 알코올형 3,500은 별도 한도입니다.","설계농도(%) = 소화농도(%) × A·B·C급 화재별 안전계수 이상. 사람이 상주하는 곳은 최대허용 설계농도를 초과할 수 없다.":"설계농도는 소화농도에 A·B·C급 안전계수를 곱한 값 이상이며 사람이 상주하는 곳은 최대허용 설계농도를 넘을 수 없습니다.","설계농도가 34 % 이상인 방호대상물은 기본 소화약제량에 그림의 보정계수를 곱한다.":"설계농도가 34 % 이상이면 기본 약제량에 보정계수를 곱해 늘립니다.","설계밀도 이상의 고체에어로졸을 방호구역 전체에 균일하게 방출하는 설비로서 분산(Dispersed)방식이 아닌 압축(Condensed)방식.":"고체에어로졸소화설비는 설계밀도 이상의 에어로졸을 방호구역 전체에 균일하게 내보내는 압축방식 설비입니다.","설비 기동 시 자동으로 폐쇄되어야 한다. 비상전원은 최소 20분 이상 유효하게 공급. 과압배출구를 설치한다.":"방호구역은 설비가 기동하면 자동으로 닫히고 비상전원은 최소 20분 공급하며 과압배출구를 둡니다.","설치높이: 방호구역 바닥으로부터 0.2 m 이상 3.7 m 이하. 천장높이가 3.7 m를 초과하면 추가로 다른 열의 분사헤드를 설치. 오리피스 면적은 연결 배관구경 면적의 70 % 이하.":"분사헤드는 바닥에서 0.2 m 이상 3.7 m 이하에 달고 천장이 3.7 m를 넘으면 열을 더하며 오리피스는 배관 면적의 70 % 이하입니다.","소용량, 고양정, 고점도 액체의 수송이 가능하다. 송출량의 맥동이 없고 구조가 간단하다.":"회전펌프는 점도가 높은 액체도 보내고 송출량 맥동이 없으며 구조가 간단한 장점이 있습니다.","소유량·고양정에는 부적합하고, 양정은 임펠러 지름과 회전수가 클수록 커진다. 다단으로 양정을 높인다.":"원심펌프는 소유량·고양정에는 맞지 않고 임펠러 지름과 회전수가 클수록 양정이 크며 다단으로 높입니다.","소화농도에 안전율을 고려한 농도. 최대허용 설계농도: 사람이 상주하는 곳에 적용하는, 인체 안전에 영향을 미치지 않는 농도.":"설계농도는 소화농도에 안전율을 반영한 농도이고 최대허용 설계농도는 사람이 있어도 안전한 상한 농도입니다.","소화약제의 중량과 저장용기 내부 용적의 비(중량/용적). 충전비와 반대.":"충전밀도는 약제 중량을 용기 내부 용적으로 나눈 값이라 용적을 중량으로 나누는 충전비와 반대입니다.","속도분포 u(y)를 y로 미분해 바닥(y=0)의 du/dy를 구한 뒤 μ = τ ÷ (du/dy). 예) u = 5y − y², du/dy(0) = 5, τ 0.01 Pa → μ = 0.002 Pa·s = 2×10⁻³.":"속도분포를 y로 미분해 바닥에서의 기울기를 구한 뒤 전단응력을 그 값으로 나누어 점성계수를 얻습니다.","손실수두는 1/3⁴ = 1/81배.":"지름이 3배가 되면 손실수두는 3의 네제곱 분의 일인 81분의 1로 줄어듭니다.","손실수두를 더한다: P₁/γ + V₁²/2g + Z₁ = P₂/γ + V₂²/2g + Z₂ + h_L.":"실제유체는 마찰로 에너지를 잃으므로 하류 쪽 식에 손실수두를 더해야 양쪽이 맞습니다.","수동식 기동장치는 제어반마다 설치하고, 방출지연스위치를 설치한다. 오작동 제어를 위해 제어반 인근에 설비정지스위치를 설치한다.":"수동식 기동장치는 제어반마다 방출지연스위치와 함께 두고 오작동 대비 설비정지스위치를 제어반 근처에 둡니다.","수면 아래 평면에 작용하는 전압력 F = γ·h_c·A. h_c는 도심까지 깊이, A는 면적.":"수면 아래 평면에 작용하는 전압력은 단위중량, 도심까지 깊이, 면적을 곱한 값입니다.","수면표고차 = 손실수두로 놓는다 → D⁵ = 8fLQ² ÷ (π²g·h) → 5제곱근. 문항에 f 조건 누락(정답은 약 633 mm).":"수면 높이차를 손실수두로 놓고 지름의 5제곱을 구한 뒤 5제곱근을 취하며 정답은 약 633 mm입니다.","수분함유율 0.2 wt% 이하. 흡습율: 중탄산나트륨 약제 0.2 wt%, 중탄산칼륨 약제 2 wt%, 인산염류 등 약제 1.5 wt% 이하.":"수분함유율은 0.2 wt% 이하이고 흡습율은 약제 종류마다 한도가 다릅니다.","수성막포를 사용하면 질식 효과로 소화할 수 있다.":"일반화재에 수성막포를 쓰면 포가 덮어 산소를 차단하는 질식 효과로 끌 수 있습니다.","수성막포와 제3종 분말소화약제를 함께 쓰면 소화효율을 높일 수 있다는 선지는 옳은 선지로 출제됐다.":"수성막포와 제3종 분말을 함께 쓰면 소화효율이 오른다는 선지가 옳다고 되어 있습니다.","수압 0.1 MPa, 6 L/min, 풍량 13 ㎥/min에서 팽창율 500배 이상, 25 % 환원시간 3분 이상.":"고발포용은 수압 0.1 MPa에서 팽창율 500배 이상이고 25 % 환원시간이 3분 이상이어야 합니다.","수용성용제(알코올류, 에테르류, 에스테르류, 케톤류, 알데히드류, 아민류, 니트릴류, 유기산 등) 소화용.":"알코올형포는 알코올류, 에테르류 같은 수용성용제 화재에 쓰는 포 약제입니다.","스위치 개방 전 정상상태에서 초기값 → 개방 후 정상상태에서 최종값 → τ를 구해 대입. 정답 5 − (1/3)e^(−2t)는 최종값 5 V, τ = 0.5초(L 2 H, R 4 Ω)인 경우.":"스위치를 열기 전 초기값과 연 뒤 최종값, 시정수 τ를 구해 식에 대입하며 이 예는 최종값 5 V, τ 0.5초입니다.","식용유화재에서 비누화반응으로 산소를 차단하고 재발화를 방지한다. 일반 ABC분말소화기보다 냉각효과가 뛰어나다.":"K급 약제는 식용유와 비누화반응을 일으켜 산소를 막고 재발화를 막으며 ABC분말보다 냉각이 잘 됩니다.","실양정(20 m) + 관 마찰손실 + 속도수두 = 전양정 → P = γQH(kW) → HP로 환산. 예) 실양정만으로는 98 kW(약 131 HP). 정답 약 170 HP는 손실수두를 더한 값(문항에 손실 조건 누락).":"실양정에 마찰손실과 속도수두를 더한 전양정으로 동력을 구하며 문항에 손실 조건이 빠져 있습니다.","실 체적 V = 가로×세로×높이 → T를 K로(℃+273) → m = PV ÷ (RT). 예) 8×8×3 = 192 m³, P 100 kPa, T 298 K, 공기 R 0.287 kJ/kg·K → 약 224.5 kg.":"방 부피를 구하고 온도를 켈빈으로 바꾼 뒤 압력과 부피의 곱을 RT로 나누어 공기 질량을 구합니다.","알루미늄, 마그네슘, 아연 등의 금속 또는 금속분말.":"금속화재 대상은 알루미늄, 마그네슘, 아연 같은 금속이나 그 분말입니다.","알칼리 금속염류 등을 주성분으로 하는 수용액으로 알칼리성 반응을 나타내야 한다.":"강화액은 알칼리 금속염류 수용액이 주성분이라 알칼리성을 띠어야 합니다.","압력수두와 속도수두 등을 합한다. 예) 2.2 kgf/cm² = 22 m, 지름 0.5 m 관 유속 5.09 m/s → 속도수두 1.32 m. Q 1 m³/s, 합계 23.3 m → 수동력 228.7 kW. 정답 268.9 kW는 효율 85%를 적용한 값(추정).":"전양정은 압력수두와 속도수두 등을 더한 값이며 정답 268.9 kW는 85% 효율을 적용한 값으로 추정합니다.","압력은 단위중량(밀도)에 비례한다. 수은 γ = 13.6 × γ물.":"압력은 단위중량에 비례하며 수은의 단위중량은 물의 13.6배입니다.","압축공기 또는 압축질소를 일정 비율로 섞어 포를 만든다.":"압축공기포 믹싱챔버방식은 압축공기나 압축질소를 일정 비율로 섞어 포를 만듭니다.","액면계 및 압력계와 2.3 ㎫ 이상 1.9 ㎫ 이하에서 작동하는 압력경보장치를 설치.":"저압식 저장용기에는 액면계와 압력계, 그리고 압력경보장치를 설치하라는 기준입니다.","액체: 온도가 오르면 점성계수가 감소한다. 기체: 온도가 오르면 점성계수가 증가한다.":"온도가 오르면 액체는 분자 간 인력이 약해져 점성계수가 줄고, 기체는 분자 충돌이 늘어 커집니다.","액체와 기체. 고체는 유체가 아니다.":"유체는 흐를 수 있는 물질이라 액체와 기체가 해당하고, 모양이 고정된 고체는 제외합니다.","액체 형태의 절연체도 존재한다(예: 절연유).":"절연체에는 절연유처럼 액체 상태인 것도 있습니다.","약 0.073 N/m(20℃, 공기 접촉).":"20℃ 공기 접촉에서 물의 표면장력은 약 0.073 N/m입니다.","약 1,700배 팽창한다(물 1 L → 약 1,700 L).":"수증기는 물 1 L가 약 1,700 L가 될 만큼 팽창하며 이 팽창이 질식 효과를 냅니다.","약 374℃. 임계온도 이상에서는 압력을 가해도 액화되지 않는다.":"임계온도 약 374℃ 이상에서는 압력을 높여도 물이 액체로 되지 않습니다.","약 79.7 cal/g. 20℃ 물 1 g을 100℃ 수증기로 만드는 데 약 619.6 cal.":"융해잠열은 약 79.7 cal/g이고 20℃ 물 1 g을 100℃ 수증기로 만들려면 약 619.6 cal가 듭니다.","약제 방출개시 후 1분 이상 경보를 계속한다. 확성기까지 수평거리 25 m 이하.":"약제를 방출하기 시작한 뒤 1분 이상 경보를 계속하며 확성기까지 수평거리는 25 m 이하입니다.","약제 방출 시 인체에 동상과 질식의 우려가 있다.":"이산화탄소를 방출하면 사람이 동상을 입거나 숨이 막힐 우려가 있습니다.","어떤 물질의 밀도(또는 단위중량)를 4℃ 물의 밀도(단위중량)로 나눈 값. 단위가 없다.":"비중은 4℃ 물과 견주는 상대값이라 단위가 붙지 않습니다.","얼음 0℃ → 100℃ 수증기: 79.7 + 100 + 539 = 약 719 cal/g.":"0℃ 얼음이 100℃ 수증기가 될 때 융해열, 가열 열량, 증발잠열을 더하면 약 719 cal/g입니다.","얼음 비열 약 0.5 cal/g·℃, 수증기 비열 약 0.47 cal/g·℃.":"얼음과 수증기의 비열은 각각 약 0.5와 0.47 cal/g·℃로 물의 비열보다 작습니다.","연소는 발열반응이다. 탄소의 1차 연소(C → CO)와 2차 연소(CO → CO₂)는 모두 발열반응.":"연소는 열을 내는 발열반응이며 탄소가 일산화탄소가 되는 1차 연소도 이산화탄소가 되는 2차 연소도 발열입니다.","열 → 전기(제벡), 전기 → 접합부 열(펠티에), 동종 금속 온도차(톰슨).":"열에서 전기가 나오면 제벡, 전기로 접합부 열이 나면 펠티에, 같은 금속의 온도차는 톰슨 효과입니다.","열분해 시 흡열반응에 의한 냉각, 불연성가스(NH₃, H₂O)에 의한 질식, 메타인산의 방진, 오르토인산의 섬유소 탈수·탄화, 분말 운무에 의한 열방사 차단, 유리된 NH₄⁺에 의한 부촉매.":"냉각, 질식, 방진, 탈수·탄화, 열방사 차단, 부촉매의 여섯 효과로 소화합니다.","염화나트륨, 흑연, 구리 등을 주성분으로 하는 분말 또는 과립 형태의 혼합물.":"D급 소화약제는 염화나트륨, 흑연, 구리 등을 주성분으로 한 분말이나 과립 혼합물입니다.","염화나트륨 주제에 고분자물질을 혼합한 소화약제로 나트륨 및 칼륨 화재에 적응성이 있다.":"Met-L-X는 염화나트륨에 고분자물질을 섞은 약제로 나트륨과 칼륨 화재에 쓸 수 있습니다.","예) Δ-Δ, 전원 400 V, 부하 12 + j16 Ω: |Z| = 20 Ω, 상전류 = 400 ÷ 20 = 20 A, 선전류 = 20√3 A.":"Δ-Δ 결선에서 부하 크기가 20 Ω이므로 상전류는 20 A이고 선전류는 20√3 A입니다.","오리피스 유속 V = √(2gh).":"토리첼리 정리는 오리피스에서 나오는 물의 유속이 수면 높이에서 자유낙하한 속도와 같다는 내용입니다.","오존층 파괴 등 환경오염에 미치는 영향이 적다. 구성원소는 플루오르, 탄소, 산소. 물보다 빨리 기화되어 연쇄반응 차단과 냉각소화를 한다.":"이 약제는 오존층에 미치는 영향이 적고 물보다 빨리 기화해 연쇄반응 차단과 냉각으로 끕니다.","와류펌프, 제트펌프, 기포펌프, 수격펌프 등.":"와류, 제트, 기포, 수격펌프는 터보형도 용적형도 아닌 특수형으로 분류합니다.","왕복펌프(피스톤, 플런저, 다이어프램)와 회전펌프(기어, 베인, 나사).":"용적형 펌프는 왕복식인 피스톤, 플런저, 다이어프램과 회전식인 기어, 베인, 나사로 나뉩니다.","용기 내부 온도 -18 ℃ 이하에서 2.1 ㎫을 유지할 수 있는 자동냉동장치를 설치.":"저압식은 용기 내부 온도 -18 ℃ 이하에서 2.1 ㎫을 유지하는 자동냉동장치를 달아야 합니다.","원심펌프(볼류트, 터빈), 사류펌프, 축류펌프. 임펠러 회전으로 속도에너지를 주고 압력으로 바꾼다.":"터보형 펌프는 임펠러를 돌려 물에 속도에너지를 주고 이를 압력으로 바꾸며 원심·사류·축류가 있습니다.","원자 단위로는 떨어져 있어도 구멍 없는 연속체로 보고 해석한다.":"분자 사이 빈틈을 무시하고 물질이 빈틈없이 이어진 것으로 보아 밀도와 압력을 한 점의 값으로 다룹니다.","윗면이 개방된 용기에 저장하는 경우, 화재 시 연소면이 한정되고 가연물이 비산할 우려가 없는 경우: 방호대상물 표면적 1 ㎡당 13 ㎏.":"윗면이 열린 용기에서 연소면이 한정되고 가연물이 튀지 않으면 표면적 1 ㎡당 13 ㎏을 씁니다.","유도전동기 동기속도 N_s = 120f/P (rpm), 슬립 s = (N_s − N)/N_s.":"동기속도는 120에 주파수를 곱해 극수로 나눈 값이고 슬립은 동기속도와 회전속도 차의 비율입니다.","유동 특성이 시간에 따라 변하는 흐름(∂U/∂t ≠ 0).":"비정상류는 같은 지점에서도 시간에 따라 속도나 압력이 달라지는 흐름입니다.","유량은 회전수 비에 비례, 전양정은 회전수 비의 제곱에 비례, 축동력은 회전수 비의 3승에 비례한다.":"회전수가 두 배가 되면 유량은 비례해 늘고 양정은 제곱, 축동력은 3승으로 늘어 동력 증가가 가장 큽니다.","유속의 제곱에 비례한다(반비례가 아님).":"마찰손실수두는 유속의 제곱에 비례하므로 유속이 커질수록 손실이 제곱으로 불어납니다.","유입, 유출, 급확대, 급축소, 점차확대, 밸브, 엘보 등 관 부속에서 생기는 손실.":"미소손실은 관이 갑자기 넓어지거나 밸브, 엘보 같은 부속을 지날 때 생기는 부차적 손실입니다.","유체가 접촉면에 주는 압력은 면에 수직으로 작용한다(경사면에도 수직).":"유체 압력은 닿은 면에 항상 수직으로 작용하므로 경사면에서도 면과 직각입니다.","유체에 전단응력이 작용할 때 변형에 저항하는 성질.":"유체에 전단응력을 주면 변형을 막으려는 저항이 생기는데 그 성질이 점성입니다.","유효흡입수두 NPSHav가 필요흡입수두 NPSHre보다 커야 공동현상이 없다(NPSHav > NPSHre).":"유효흡입수두가 필요흡입수두보다 커야 펌프 안에서 공동현상이 생기지 않습니다.","음수 계수의 sin 항은 위상을 180° 이동시켜 부호를 양으로 바꾼 뒤 비교한다.":"sin 항 계수가 음수이면 위상을 180° 돌려 계수를 양수로 만든 뒤 다른 항과 위상을 견줍니다.","음향경보는 방출 개시 후 1분 이상 계속. 비상전원은 20분 이상 작동. 자동식 기동장치의 감지기 회로는 교차회로방식.":"음향경보는 방출 후 1분 이상 울리고 비상전원은 20분 이상 작동하며 감지기 회로는 교차회로방식입니다.","이산화탄소소화약제는 소화약제의 형식승인 및 제품검사의 기술기준 적용 대상에서 제외된다.":"이산화탄소 약제는 형식승인과 제품검사 기술기준 대상이 아니므로 그 기준의 적용을 받지 않습니다.","이종 금속을 접합하여 폐회로를 만들고 두 접합점의 온도를 다르게 하면 열기전력이 생겨 열전류가 흐르는 현상.":"제벡 효과는 서로 다른 두 금속을 이어 접합점 온도를 다르게 하면 열기전력이 생겨 전류가 흐르는 현상입니다.","인덕터 저장 에너지 W = ½LI². 전류가 일정하면 인덕턴스에 비례한다.":"인덕터에 저장되는 에너지는 인덕턴스와 전류 제곱에 비례하므로 전류가 일정하면 인덕턴스에 비례합니다.","인덕턴스는 전류 변화를 방해하는 정도를 나타내는 비례상수. 전하를 축적하는 능력은 정전용량이다.":"인덕턴스는 전류가 변하는 것을 막는 정도이고 전하를 모아 두는 능력은 정전용량이라 서로 다른 양입니다.","인산염을 주성분으로 한 분말소화약제(제1인산암모늄 NH₄H₂PO₄).":"제1인산암모늄 같은 인산염이 주성분인 분말소화약제입니다.","일반기체상수 R = 8.314 J/mol·K, 공기의 기체상수 R = 287 J/kg·K, 공기 분자량 약 29. 표준상태(0℃, 1기압)에서 기체 1 mol의 부피는 22.4 L.":"일반기체상수는 8.314 J/mol·K이고 표준상태에서 기체 1 mol의 부피는 22.4 L입니다.","일정한 압력에서 기체의 부피는 절대온도에 비례한다(V/T = 일정).":"샤를의 법칙은 압력이 일정할 때 기체 부피가 절대온도에 비례한다는 것입니다.","일정한 온도에서 기체의 부피는 압력에 반비례한다(PV = 일정).":"보일의 법칙은 온도가 일정할 때 기체 부피가 압력에 반비례한다는 것입니다.","일정한 온도와 압력에서 같은 부피 속의 기체 분자 수는 같다.":"아보가드로의 법칙은 같은 온도와 압력에서 부피가 같으면 기체 분자 수도 같다는 것입니다.","입구 형상에 따라 K가 달라진다(둥근 입구 약 0.05, 돌출 입구 약 0.8).":"급축소·유입 손실계수는 입구 모양에 좌우되어 둥근 입구는 약 0.05, 돌출 입구는 약 0.8입니다.","입력이 변하는 시각마다 R₁, R₂를 순서대로 갱신한다":"입력이 바뀌는 시각마다 R₁과 R₂ 상태를 순서대로 새로 계산합니다.","자속의 방향에 수직인 단위 면적을 통과하는 자속의 수(B = Φ/A).":"자속밀도는 자속에 수직인 단위 면적을 지나는 자속의 수로, 자속을 면적으로 나눈 값입니다.","자연계의 상태변화는 엔트로피가 증가하는 방향으로 일어난다. 가역과정은 엔트로피가 변하지 않고(고립계), 비가역과정은 엔트로피가 증가한다.":"자연 상태변화는 엔트로피가 늘어나는 쪽으로 가고, 고립계의 가역과정만 엔트로피가 그대로입니다.","저발포용: 표준발포노즐로 팽창비 6배(수성막포 5배) 이상. 고발포용: 500배 이상.":"표준발포노즐로 만든 포의 팽창비가 저발포는 6배 이상, 고발포는 500배 이상이어야 하고 수성막포는 5배 이상입니다.","저장량은 계산식 산출량에 1.1을 곱한 양 이상.":"국소방출 저장량은 계산식으로 나온 양에 1.1을 곱한 값 이상이어야 합니다.","저장용기는 방호구역 외의 장소로서 방화구획된 실에 설치한다.":"저장용기는 방호구역 밖의 방화구획된 실에 둡니다.","저장용기에는 정압작동장치, 잔류 약제 청소장치를 설치하고, 축압식에는 사용압력 범위를 표시한 지시압력계를 설치한다.":"저장용기에 정압작동장치와 청소장치를 달고 축압식은 지시압력계로 사용압력 범위를 보여 줍니다.","저장용기와 선택밸브(또는 개폐밸브) 사이 안전장치는 배관의 최소사용설계압력과 최대허용압력 사이에서 작동. 소화가스는 전용배관으로 건축물 외부로 배출. 안전장치로 용전식은 쓸 수 없다.":"저장용기와 선택밸브 사이 안전장치는 배관의 최소사용설계압력과 최대허용압력 사이에서 작동하고 용전식은 쓰지 못합니다.","저장용기와 선택밸브(또는 개폐밸브) 사이에 과압방지 안전장치를 설치하고, 안전장치로 나온 소화가스는 전용배관으로 건축물 외부로 배출한다.":"저장용기와 선택밸브 사이에 과압방지 안전장치를 두고 나온 소화가스는 전용배관으로 건물 밖에 배출합니다.","저장용기와 선택밸브 사이 집합배관에 수동잠금밸브를 설치하되 선택밸브 직전에 설치한다.":"수동잠금밸브는 저장용기와 선택밸브 사이 집합배관 중 선택밸브 바로 앞에 설치합니다.","저장용기와 집합관 사이 연결배관에 체크밸브를 설치한다. 다만 저장용기가 하나의 방호구역만 담당하면 제외.":"저장용기와 집합관 사이 연결배관에 체크밸브를 두되 용기가 방호구역 하나만 맡으면 생략합니다.","저장용기의 약제량 손실이 5 %를 초과하거나 압력손실이 10 %를 초과하면 재충전하거나 교체한다. 다만 불활성기체 소화약제 저장용기는 압력손실이 5 %를 초과하면 재충전하거나 교체한다.":"약제량이 5 %를 넘게 줄거나 압력이 10 %를 넘게 떨어지면 재충전하며 불활성기체는 압력손실 5 %가 기준입니다.","저장용기의 충전비는 0.8 이상으로 한다(제1종~제4종 모두).":"분말 저장용기 충전비는 제1종부터 제4종까지 모두 0.8 이상이어야 합니다.","저항률(resistivity)의 단위는 Ω·m이다(Ω/m가 아님).":"저항률의 단위는 옴 미터(Ω·m)이며 Ω/m가 아닙니다.","전기식·가스압력식 또는 기계식으로 자동 개방되고 수동으로도 개방되며 안전장치가 부착된 것.":"개방밸브는 전기식, 가스압력식, 기계식으로 자동 개방되고 수동으로도 열리며 안전장치가 붙은 것입니다.","전기식 기동장치로 7병 이상의 저장용기를 동시에 개방하는 설비는 2병 이상에 전자 개방밸브를 부착한다. 가스압력식 기동용가스용기: 25 ㎫ 이상 압력에 견딜 것, 5 L 이상, 질소 등은 6.0 ㎫ 이상(21 ℃) 충전.":"전기식은 7병 이상을 동시에 열면 2병 이상에 전자 개방밸브를 달고 가스압력식 기동용 용기는 25 ㎫ 이상 압력을 견뎌야 합니다.","전기 전도성이 없을 것. 약제 방출 후 재발화 방지를 위해 최소 10분간 소화밀도를 유지할 것. 비상주장소에 한하여 설치할 것. 방호구역의 밀폐성을 확보할 것.":"에어로졸 설비는 비전도성이어야 하고 방출 뒤 재발화를 막으려 최소 10분간 소화밀도를 유지해야 합니다.","전기 절연성이 우수하여 전기화재에 적응성이 있다.":"이산화탄소는 전기를 통하지 않는 절연성이 좋아 전기화재에 쓸 수 있습니다.","전기화재에 무상으로 방사하는 경우 사용할 수 있다.":"강화액은 전기화재에 무상으로 방사할 때 쓸 수 있습니다.","전단응력 τ = μ·du/dy. 점성계수 μ는 전단응력과 속도경사 사이의 비례상수.":"전단응력은 속도경사에 점성계수를 곱한 값이며, 점성계수가 그 비례상수라는 법칙입니다.","전류법칙(KCL): 한 점으로 들어오는 전류의 합 = 나가는 전류의 합. 전압법칙(KVL): 폐회로의 전압 상승의 합 = 전압 강하의 합.":"키르히호프 전류법칙은 한 점에서 들어오는 전류의 합이 나가는 합과 같고 전압법칙은 폐회로 전압 상승의 합이 강하의 합과 같습니다.","전역방출·국소방출 모두 저장량을 30초 이내에 방출. 호스릴은 수평거리 15 m 이하.":"저장량은 전역·국소 어느 방식이든 30초 이내에 방사해야 하고 호스릴 수평거리는 15 m까지 허용됩니다.","전역방출 심부화재 방호대상물: 7분 이내에 방사. 이 경우 설계농도가 2분 이내에 30 %에 도달해야 한다.":"심부화재 전역방출은 7분 이내 방사이며 설계농도가 2분 이내에 30 %에 닿아야 합니다.","전역방출 표면화재 방호대상물: 1분 이내에 방사.":"표면화재 전역방출은 약제를 1분 안에 쏴야 합니다.","전원 내부 임피던스 Zs = Rs + jXs, 부하가 순저항 R_L 하나인 경우: 부하 전력이 최대가 되는 R_L = |Zs| = √(Rs² + Xs²). 예) Zs = 4 + j3 → R_L = 5 Ω.":"부하가 순저항이면 전원 내부 임피던스의 크기와 같을 때 전력이 최대이고 4 + j3이면 5 Ω입니다.","전자장 해석의 미분연산: ∇V는 스칼라 함수의 변화율(경도, gradient). 벡터 E의 발산(divergence)은 단위 체적에서 발산하는 선속수로 ∇·E로 표시. 회전은 ∇×E. 라플라시안은 ∇·∇ = ∇².":"경도는 스칼라 함수의 변화율, 발산은 단위 체적에서 나가는 선속수이며 회전과 라플라시안도 미분연산입니다.","전하는 도체 표면에만 분포하고 내부에는 없다. 내부 전기장은 0이다. 표면은 등전위면이고 내부 전위는 표면 전위와 같다. 표면에서 전기장은 표면에 수직이다.":"완전 도체에서는 전하가 표면에만 분포하고 내부 전기장은 0이며 표면은 등전위면입니다.","절대압력 = 대기압 + 게이지압력. 진공압 = 대기압 − 절대압력.":"절대압력은 대기압에 게이지압력을 더한 값이고, 진공압은 대기압에서 절대압력을 뺀 값입니다.","정답은 R₁이 1~7, 21~25 구간, R₂가 9~18 구간에서 On인 선지":"R₁이 1~7과 21~25 구간, R₂가 9~18 구간에서 켜지는 선지가 정답입니다.","정상류, 비압축성, 비점성(마찰 없음), 같은 유선을 따르는 흐름.":"베르누이 방정식은 정상류, 비압축성, 마찰 없는 유체가 같은 유선을 따를 때만 성립합니다.","정전하에서 나와 부전하로 들어간다. 서로 교차하지 않는다. 등전위면과 직교한다. 도체 표면에 수직이다. 밀도는 전계의 세기와 같다. 접선 방향이 전계의 방향과 일치한다.":"전기력선은 정전하에서 나와 부전하로 들어가고 서로 교차하지 않으며 등전위면과 직교합니다.","정지 유체 안의 압력 P = P₀ + γh. 자유수면 아래 한 점의 압력은 수심이 깊어질수록 증가한다.":"정지 유체 속 압력은 표면 압력에 깊이와 단위중량의 곱을 더한 값이라 깊을수록 커집니다.","정지 유체의 압력은 깊이와 유체의 단위중량으로 정해지고 용기 모양과 무관하다.":"정지 유체의 압력은 깊이와 단위중량만으로 정해져 용기 모양이 달라도 같은 깊이면 같습니다.","정지 유체의 한 점에 작용하는 압력은 모든 방향에서 같다.":"한 점의 정지 유체 압력은 방향에 관계없이 같은 크기이며 이를 등방성이라 합니다.","제1종 0.8 L, 제2종 1.0 L, 제3종 1.0 L, 제4종 1.25 L(표는 원문 이미지로 텍스트 미확인, 기출 선지와 일치).":"약제 1 kg당 용기 내용적은 종별로 달라 제1종 0.8 L, 제2종·제3종 1.0 L, 제4종 1.25 L입니다.","제1종·제2종·제4종은 B·C급, 제3종은 A·B·C급.":"제1종·제2종·제4종 분말은 B·C급 화재에, 제3종 분말은 A·B·C급 화재에 적응합니다.","제3종 분말의 열분해 생성물 중 섬유소의 탈수·탄화작용을 하는 것은 오르토인산(H₃PO₄)이다.":"제3종 분말 분해물 중 섬유소를 탈수·탄화시키는 물질은 오르토인산입니다.","제3종 분말이 다른 분말과 달리 A급 화재에 적용되는 이유: 메타인산의 방진효과(ㄷ)와 오르토인산에 의한 섬유소의 탈수·탄화작용(ㄹ). 냉각·질식·열방사 차단·부촉매는 다른 분말에도 공통이다.":"제3종 분말이 A급 화재에 쓰이는 까닭은 메타인산의 방진과 오르토인산의 탈수·탄화 작용 때문입니다.","제4종 분말은 회색(보충), 제2종 분말은 담회색(자색 계열로 부르던 교재도 있음).":"제4종 분말은 회색, 제2종 분말은 담회색으로 보는데 자색 계열로 부른 교재도 있습니다.","주된 소화효과는 억제소화(부촉매, 연쇄반응 차단). 할로겐 원소의 소화효과 크기는 I > Br > Cl > F, 안정성은 반대.":"할론은 연쇄반응을 끊는 억제소화가 주된 효과이며 할로겐 소화효과는 I, Br, Cl, F 순으로 크고 안정성은 그 반대입니다.","주로 발전소에서 전압을 높여 전력전송을 위해 사용한다.":"Δ-Y 결선은 발전소에서 전압을 높여 송전할 때 주로 씁니다.","주방(식용유)화재용이며 A·B·C급에 두루 적응성이 좋은 약제가 아니다. 가연성 금속화재에도 적응성이 없다.":"K급 약제는 주방화재용이라 A·B·C급 전반에 쓰는 약제가 아니며 금속화재에도 맞지 않습니다.","주어진 온도에서 순수 물질이 상변화를 하는 압력.":"온도를 정하면 순수 물질이 액체에서 기체로 바뀌는 압력이 하나로 정해지며 이것이 포화압력입니다.","주원료에 포 안정제 등을 첨가한 액상으로 물과 일정 농도로 혼합한 뒤 공기를 기계적으로 혼입시켜 거품을 만들어 소화한다.":"포소화약제는 물과 섞고 공기를 기계적으로 넣어 거품을 만들어 소화하는 액상 약제입니다.","주회법칙(∮H·dℓ = I)은 전류에 의한 자계의 세기를 구하는 데 사용한다. 암페어의 오른나사 법칙은 전류와 자계 방향 관계.":"암페어 주회법칙은 전류가 만드는 자계의 세기를 구하는 식이고 오른나사 법칙은 전류와 자계의 방향 관계입니다.","중량을 체적으로 나눠 γ를 구한다 → 9,800 N/m³로 나눈다. 예) 5 m³, 98,000 N이면 γ = 19,600 → 비중 2.0.":"중량을 부피로 나눈 단위중량을 물의 9,800 N/m³로 나누면 비중이 나오며 이 예는 2.0입니다.","중력장 안에서 고도에 따라 시스템이 가지는 에너지. 속도에 따른 에너지는 운동에너지.":"높이가 높을수록 위치에너지가 크고, 속도에서 나오는 에너지는 운동에너지로 따로 부릅니다.","중탄산나트륨 약제는 NaHCO₃ 90 wt% 이상, 중탄산칼륨 약제는 KHCO₃ 90 wt% 이상, 인산염류 등 약제는 제1인산암모늄 등 함량 75 wt% 이상(설계값 -5 %~+15 %).":"주성분 함량은 중탄산염 약제가 90 wt% 이상, 인산염류 약제가 75 wt% 이상(설계값 -5 %~+15 %)입니다.","지락사고 검출이 용이하지 않다. 변압기 1대 고장 시 V결선으로 운전 가능.":"Δ-Δ 결선은 지락사고 검출이 쉽지 않고 변압기 1대가 고장 나도 V결선으로 운전할 수 있습니다.","지름 100 mm, 5 m/s → Q = (π × 0.1²/4) × 5 = 0.039 m³/s.":"지름 100 mm 관의 단면적에 5 m/s를 곱하면 유량이 약 0.039 m³/s로 나옵니다.","지름 2 mm 유리관, 0.25 cm³/s → V = Q ÷ A = 0.0796 m/s → Re = VD/ν → f = 64/Re ≈ 0.4 수준(ν 조건 누락).":"유리관 유량에서 유속과 레이놀즈수를 거쳐 f를 얻는 순서이며 동점성계수 조건이 문항에 빠져 있습니다.","지상 1층·피난층으로서 개구부 유효면적 합계가 바닥면적의 15 % 이상인 부분, 또는 전기설비·화기 사용 부분의 바닥면적이 구획 바닥면적의 5분의 1 미만인 부분. 차고·주차 용도는 제외.":"호스릴은 개구부 유효면적이 바닥면적의 15 % 이상인 지상 1층·피난층 등에 두며 차고·주차 용도는 제외합니다.","직렬 운전은 유량 같고 양정이 합해지며, 병렬 운전은 양정 같고 유량이 합해진다.":"펌프를 직렬로 잇는 것은 높은 양정이 필요할 때, 병렬은 많은 유량이 필요할 때 쓰는 구성입니다.","직렬 합성저항 R = R₁ + R₂ + …, 병렬 합성 1/R = 1/R₁ + 1/R₂ + …":"직렬은 저항을 모두 더하고 병렬은 저항의 역수를 모두 더해 합성저항을 구합니다.","직렬회로의 전압은 저항비로 나뉜다(분압). 전체 저항비에서 한 부분의 전압을 알면 나머지를 비례로 구한다.":"직렬회로의 전압은 저항 크기에 비례해 나뉘므로 한 부분의 전압을 알면 나머지는 비로 구합니다.","질량보존 법칙을 유체 흐름에 적용한 식이 연속방정식이다. 베르누이 방정식은 에너지보존 법칙을 적용한 식이다.":"연속방정식은 질량보존을, 베르누이 방정식은 에너지보존을 유체 흐름에 적용한 식입니다.","질소 52±4 vol%, 아르곤 40±4 vol%, 이산화탄소 8~9 vol%. 헬륨은 포함되지 않는다.":"이 약제는 질소 52±4, 아르곤 40±4, 이산화탄소 8~9 vol%이며 헬륨은 들어 있지 않습니다.","질소가스 또는 이산화탄소로 한다.":"가압용과 축압용 가스는 질소나 이산화탄소를 씁니다.","천장이나 벽면 상부에 설치, 하나의 방호구역에는 동일 제품군·동일 크기를 설치, 방호구역 높이는 형식승인 받은 최대 설치높이 이하, 인체·가연물과 최소 열 안전이격거리 준수.":"발생기는 천장이나 벽 상부에 달고 한 구역에는 같은 제품군·크기를 쓰며 인체·가연물과 열 안전이격거리를 둡니다.","축압식 분말소화기의 충압가스: 질소, 헬륨, 이산화탄소는 기출 선지로 옳게 출제, 일산화탄소는 충압가스가 아니다.":"축압식 소화기에 채우는 가스는 질소, 헬륨, 이산화탄소이고 일산화탄소는 포함되지 않습니다.","출력 접점(또는 출력)을 입력 OR로 되먹임하여, 시동 입력이 꺼져도 출력이 유지되는 회로.":"자기유지는 출력을 입력 쪽에 OR로 되돌려 시동 입력이 꺼져도 출력이 유지되게 하는 회로입니다.","충전비 1.6, 68 L: 68 ÷ 1.6 = 42.5 kg/병, 230 kg ÷ 42.5 = 5.4 → 6병.":"충전비 1.6, 68 L 용기는 병당 42.5 kg이므로 230 kg은 5.4병이라 6병이 필요합니다.","층류, 난류, 천이류. 사류는 해당하지 않는다.":"레이놀즈수로 구분하는 것은 층류, 난류, 천이류이며 사류는 프루드수의 영역입니다.","층류 Re < 2,100(약 2,000), 천이류 약 2,100~4,000, 난류 Re > 4,000.":"원형관에서 레이놀즈수가 2,100 아래면 층류, 4,000 위면 난류이고 그 사이가 천이류입니다.","침입도시험기(penetrometer)로 시험하여 15 mm 이상 침투되어야 한다(2023 기출은 10 mm 이하를 틀린 선지로 출제).":"침입도시험기로 분말에 15 mm 이상 침투되어야 하며 10 mm 이하는 틀린 선지였습니다.","침전량 0.1 vol% 이하(원심분리), 인화점 60 ℃ 이상.":"침전량은 원심분리로 재어 0.1 vol% 이하이고 인화점은 60 ℃ 이상이어야 합니다.","칼륨의 중탄산염이 주성분인 약제는 담회색, 인산염 등이 주성분인 약제는 담홍색 또는 황색으로 착색하고 서로 혼합하지 않는다. 제1종은 백색.":"칼륨 중탄산염 약제는 담회색, 인산염 약제는 담홍색이나 황색으로 칠하고 서로 섞지 않으며 제1종은 백색입니다.","탄산수소나트륨(NaHCO₃, 중탄산나트륨)을 주성분으로 한 분말소화약제.":"탄산수소나트륨이 주성분이며 중탄산나트륨이라고도 부르는 분말소화약제입니다.","탄산수소칼륨(KHCO₃)을 주성분으로 한 분말소화약제.":"탄산수소칼륨이 주성분인 분말소화약제입니다.","탄산수소칼륨과 요소가 화합된 분말소화약제.":"탄산수소칼륨과 요소를 화합시켜 만든 분말소화약제입니다.","탄산칼륨(K₂CO₃) 또는 초산칼륨(CH₃COOK) 등.":"K급 약제의 주성분은 탄산칼륨이나 초산칼륨 같은 칼륨염입니다.","탄소(C) 수, 불소(F) 수, 염소(Cl) 수, 브롬(Br) 수 순서.":"할론 번호는 탄소, 불소, 염소, 브롬의 원자 수를 차례로 붙인 것입니다.","탄화불소계 계면활성제를 주성분으로 물의 표면장력을 낮추어 기름 표면에 수성막을 만든다.":"수성막포는 탄화불소계 계면활성제가 물의 표면장력을 낮춰 기름 위에 수성막을 만듭니다.","팽창율 6배(수성막 5배) 이상 10배 미만, 25 % 환원시간 2분 이상.":"방수포용은 팽창율이 6배(수성막 5배) 이상 10배 미만이고 환원시간이 2분 이상입니다.","팽창질석을 사용하여 금속화재 표면을 덮어 질식소화할 수 있다.":"팽창질석으로 금속 표면을 덮으면 공기가 막혀 질식소화가 됩니다.","펌프 내부에서 유속이 급변하거나 와류, 유로 장애 등으로 압력이 포화수증기압 근처 또는 이하로 낮아져 용존 기체가 분리되고 물이 기화하여 공동이 생기는 현상.":"공동현상은 펌프 안 압력이 포화수증기압 부근까지 떨어져 물이 증발해 기포 공동이 생기는 현상입니다.","펌프와 발포기 중간에 설치된 벤추리관 부분의 차압과 가압수로 약제 탱크 안의 약제를 혼합한다(탱크 내 격막 사용).":"프레져 푸로포셔너는 벤추리관의 차압과 가압수로 격막이 있는 약제 탱크 안 약제를 섞습니다.","펌프와 발포기 중간에 설치된 벤추리관의 벤추리작용으로 포소화약제를 흡입·혼합한다.":"라인 푸로포셔너는 펌프와 발포기 사이 벤추리관에서 생기는 흡입 작용으로 약제를 빨아들여 섞습니다.","펌프 운전 중 압력과 유량이 주기적으로 변동하는 현상. H-Q 곡선이 우상향(산형) 구간에서 운전할 때 일어난다.":"서징은 펌프 운전 중 압력과 유량이 주기적으로 흔들리는 현상이며 H-Q 곡선의 우상향 구간에서 일어납니다.","펌프 토출관과 흡입관 사이에 바이패스관을 두고 그 사이에 혼합기를 설치해 약제를 흡입·혼합한다.":"펌프 푸로포셔너는 토출관과 흡입관 사이 바이패스관에 혼합기를 두어 약제를 흡입·혼합합니다.","펌프 토출측 배관에 압입기를 설치하여 약제를 압입한다.":"프레져사이드 푸로포셔너는 펌프 토출측 배관에 압입기를 두어 약제를 밀어 넣는 방식입니다.","평균유속의 2배(관 중심).":"층류에서 관 중심의 최대유속은 평균유속의 2배입니다.","표면장력 σ에 비례하고 관의 지름 d에 반비례한다. 밀도(단위중량)와 중력가속도에도 반비례한다.":"높이는 표면장력이 클수록 크고 관이 가늘수록 높아지며, 단위중량과 중력가속도가 클수록 낮아집니다.","표준발포노즐(수압 0.7 MPa, 10 L/min)에서 팽창율 6배(수성막 5배) 이상, 25 % 환원시간 1분 이상.":"저발포용은 표준발포노즐에서 팽창율 6배(수성막 5배) 이상이고 25 % 환원시간이 1분 이상이어야 합니다.","표준상태(0 ℃, 1기압) 기체 1 mol = 22.4 L, 이산화탄소 분자량 44. 예) 44.8 ㎥ = 2,000 mol × 44 g = 88 kg.":"표준상태에서 기체 1 mol은 22.4 L이므로 이산화탄소 44.8 ㎥는 2,000 mol이고 질량은 88 kg입니다.","플루오르화수소(HF)의 발생량은 화염의 크기, 소화농도, 화재진압시간에 비례한다.":"화염이 크고 소화농도가 높고 진압 시간이 길수록 독성 가스인 플루오르화수소가 많이 생깁니다.","피상전력 S = VI (VA), 유효전력 P = VI·cosθ (W), 무효전력 Q = VI·sinθ (Var). S² = P² + Q².":"피상전력은 전압과 전류의 곱이고 유효전력은 여기에 cosθ, 무효전력은 sinθ를 곱하며 피상전력 제곱은 두 전력 제곱의 합입니다.","필요 산소 mol → 동반 N₂ mol → 생성물 합계(N₂ 포함) → N₂ ÷ 합계. 예) 메탄 1 mol: O₂ 2 mol, N₂ 7.52 mol, 생성물 CO₂ 1 + H₂O 2 + N₂ 7.52 = 10.52 mol → N₂ 71.5%.":"필요한 산소량에서 따라오는 질소량을 구해 생성물 합계를 내고, 질소를 합계로 나누면 부피비가 나옵니다.","한 점에서 유동 특성이 시간에 따라 변하지 않는 흐름(∂U/∂t = 0). 모든 점에서 변하지 않는 흐름을 말한다.":"정상류는 한 점의 유동 특성이 시간이 지나도 변하지 않는 흐름입니다.","할로겐화합물(할론 1301, 할론 2402, 할론 1211 제외) 및 불활성기체로서 전기적으로 비전도성이며 휘발성이 있거나 증발 후 잔여물을 남기지 않는 소화약제.":"할로겐화합물 및 불활성기체 소화약제는 할론 1301, 2402, 1211을 뺀 비전도성 약제로 증발 뒤 잔여물이 없습니다.","할로겐화합물소화약제는 10초 이내, 불활성기체소화약제는 A·C급 화재 2분, B급 화재 1분 이내에 최소설계농도의 95 % 이상에 해당하는 약제량이 방출되도록 한다.":"할로겐화합물은 10초, 불활성기체는 A·C급 2분, B급 1분 안에 최소설계농도의 95 % 이상이 방출되게 합니다.","할로겐화합물소화약제는 10초 이내에 방호구역 각 부분에 최소설계농도의 95 % 이상에 해당하는 약제량이 방출되어야 한다.":"할로겐화합물 약제는 방출 10초 안에 방호구역 어디서나 최소설계농도의 95 %에 이르러야 합니다.","할론 1301: CF₃Br(브로모트리플루오로메탄). 할론 1211: CF₂ClBr. 할론 2402: C₂F₄Br₂. 할론 1011: CH₂ClBr. 할론 104: CCl₄.":"할론 1301은 CF₃Br, 할론 1211은 CF₂ClBr, 할론 2402는 C₂F₄Br₂로 번호가 원자 수에 대응합니다.","할론 1301 약 10, 할론 2402 약 6, 할론 1211 약 3. 할론 1301이 가장 크다.":"오존파괴지수는 할론 1301이 약 10으로 가장 크고 할론 2402는 약 6, 할론 1211은 약 3입니다.","할론 1301은 기체, 할론 1211은 기체(액화 용이), 할론 2402는 액체.":"상온·상압에서 할론 1301은 기체, 할론 1211은 액화가 쉬운 기체, 할론 2402는 액체입니다.","할론 2402는 에테인(ethane, C₂) 유도체다.":"할론 2402는 탄소가 두 개인 에테인 유도체입니다.","합성 C → Q = C_합성·V → 개별 전압 V_i = Q/C_i. 예) 2, 3, 5 μF, 800 V: C = 0.9677 μF, Q = 774 μC → C₂ 전압 = 774 ÷ 3 = 258 V.":"합성 용량으로 전하량을 구한 뒤 각 콘덴서의 전하를 용량으로 나누면 전압이 나오며 이 예는 258 V입니다.","합성계면활성제포는 질식·냉각 효과를 낸다. 할로겐화합물소화약제(HFC 계열 등)는 냉각과 일부 화학적(억제) 효과를 낸다. 제3종 분말(NH₄H₂PO₄)은 냉각·질식·방진·탈수탄화·부촉매 등 복합 효과를 낸다.":"합성계면활성제포는 질식과 냉각, 할로겐화합물은 냉각과 일부 억제, 제3종 분말은 여러 효과가 겹친 복합 소화입니다.","합성 정전용량 1/C = 1/C₁ + 1/C₂ + … 으로 감소한다. 전하량 Q는 모두 같고 전압은 정전용량에 반비례하여 나뉜다(정전용량이 작은 콘덴서에 전압이 많이 걸린다).":"직렬로 이으면 합성 정전용량은 줄고 전하량은 같으며 용량이 작은 콘덴서에 전압이 많이 걸립니다.","합성 정전용량 C = C₁ + C₂ + … 이고 총 전하량은 각 콘덴서 전하량의 합과 같다.":"병렬로 이으면 합성 정전용량은 각 용량의 합이고 총 전하량도 각 전하량의 합입니다.","헬륨, 네온, 아르곤 또는 질소가스 중 하나 이상의 원소를 기본성분으로 하는 소화약제.":"불활성기체소화약제는 헬륨, 네온, 아르곤, 질소가스 중 하나 이상을 기본성분으로 합니다.","현열(m·c·ΔT) → 증발잠열(m·r)을 더한다. 얼음이면 융해열을 먼저 더한다.":"냉각효과는 현열을 먼저 구하고 증발잠열을 더하며, 얼음이면 융해열을 맨 앞에 더합니다.","호스릴이산화탄소소화설비는 하나의 노즐에 대하여 90 ㎏ 이상. 노즐은 20 ℃에서 노즐마다 60 ㎏/min 이상 방출. 호스접결구까지 수평거리 15 m 이하.":"호스릴 설비는 노즐 하나에 90 ㎏ 이상이며 20 ℃에서 노즐마다 분당 60 ㎏ 이상 방출하고 접결구까지 15 m 이하입니다.","확산계수로 나타낸다. 확산계수 3.5 이상(20±2 ℃, 사이클로헥세인). 20 ℃의 사이클로헥세인 액면 위에 수성막을 형성할 수 있어야 한다.":"수성막 성능은 확산계수로 나타내며 20 ℃ 사이클로헥세인 액면에 수성막이 생겨야 하고 값은 3.5 이상입니다.","회전수 N, 지름 D가 변할 때: 유량 Q ∝ N·D³, 전양정 H ∝ N²·D², 축동력 P ∝ N³·D⁵.":"상사법칙은 유량이 회전수와 지름 세제곱에, 양정이 둘의 제곱에, 동력이 회전수 세제곱·지름 다섯제곱에 비례한다는 내용입니다.","회전펌프는 회전수로 토출량을 조절한다. 행정으로 조절하는 것은 왕복펌프의 방식이다(회전펌프에는 행정이 없다).":"회전펌프는 행정이 없어 회전수로 토출량을 조절하고, 행정 조절은 왕복펌프의 방식입니다.","힘 [MLT⁻²]=[F], 압력 [FL⁻²], 속도 [LT⁻¹], 가속도 [LT⁻²], 유량 [L³T⁻¹].":"힘, 압력, 속도, 가속도, 유량의 차원을 질량·길이·시간 기호로 한꺼번에 적은 표기입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
